-- ----- Activities: Vocal Warm-Ups area -----

-- [Vocal Warm-Ups] Shake Hands Chant
UPDATE activities
SET activity = 'Shake Hands Chant',
    time = 3,
    description = '<p>Start the session with Shake Hands Chant to wake the body. Shake hands up in the air as you chant ''And an up, shake, shake, shake, shakedy shake'', ''and a down shake, shake, shake, shakedy shake'' with the….</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Shake hands up in the air as you chant ''And an up, shake, shake, shake, shakedy shake'', ''and a down shake, shake, shake, shakedy shake'' with the appropriate actions.</li><li>Repeat twice before ''To the front, to the back, to the s-s-side'' x2.</li><li>Then ''Go around and around'' with a stirring type action, as if stirring something in a large cauldron.</li><li>Repeat but getting gradually faster.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Shake Hands Chant taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Shake Hands Chant, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Shake Hands Chant and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '03726c3c-53fe-47cc-becd-31ce68dd5a97';

-- [Vocal Warm-Ups] Rub and Shake Hands
UPDATE activities
SET activity = 'Rub and Shake Hands',
    time = 3,
    description = '<p>Start the session with Rub and Shake Hands to wake the body. Rub hands together, shake hands out and in and up and down.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Rub hands together, shake hands out and in and up and down.</li><li>Mix the order up.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Rub and Shake Hands taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Rub and Shake Hands, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Rub and Shake Hands in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Add an opposite pattern or faster swap on a shared cue.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '8869bf37-3e85-45e2-92e7-afa135f5c641';

-- [Vocal Warm-Ups] Side Bend Stretch
UPDATE activities
SET activity = 'Side Bend Stretch',
    time = 3,
    description = '<p>Start the session with Side Bend Stretch to wake the body. Put feet together and raise arms in a v-shape above the head.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Put feet together and raise arms in a v-shape above the head.</li><li>Bend over to the right then to the left which will help to stretch singing muscles.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Side Bend Stretch, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Side Bend Stretch in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'd30e322e-1343-474b-9694-584992f84bba';

-- [Vocal Warm-Ups] Posture Check
UPDATE activities
SET activity = 'Posture Check',
    time = 3,
    description = '<p>Start the session with Posture Check to wake the body. Check posture by making sure that ears are over shoulders.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Check posture by making sure that ears are over shoulders.</li><li>Shoulders are over hips and hips are over ankles.</li><li>Stretch both hands up into the air so that the rib cage is opened up.</li><li>As the arms are lowered, try to keep the same openness in the rib cage.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Posture Check, hands on ribs/tummy stay light — expansion should be sideways/forwards, not a heaved chest.</li><li>Model the Posture Check posture check once, then let pairs self-check: ears over shoulders, soft knees.</li><li>After Posture Check, shake out once, then find ‘singer’s feet’ before the first note.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '1fc4da98-22e4-43e6-8c97-5058dd1a3c1a';

-- [Vocal Warm-Ups] My Bonny Letter B
UPDATE activities
SET activity = 'My Bonny Letter B',
    time = 3,
    description = '<p>Start the session with My Bonny Letter B to wake the body. Sing ''My bonny lies over the ocean'', standing up and sitting down each time a word is sung that begins with the letter B.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sing ''My bonny lies over the ocean'', standing up and sitting down each time a word is sung that begins with the letter B.</li><li>Then add a clap on every word which contains the letter ''O''.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Spot every B in My Bonny Letter B spoken once, then sing; celebrate clean sit/stand changes without collapsing posture.</li><li>During My Bonny Letter B, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of My Bonny Letter B and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '517eae7a-d80d-4b37-bc62-e5a6aacbc09d';

-- [Vocal Warm-Ups] Shower Tap Wake-Up
UPDATE activities
SET activity = 'Shower Tap Wake-Up',
    time = 3,
    description = '<p>Start the session with Shower Tap Wake-Up to wake the body. Imagine you are having a bit of a shower – quickly tap with both hands up your legs, along both arms, down your front etc.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Imagine you are having a bit of a shower – quickly tap with both hands up your legs, along both arms, down your front etc.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Shower Tap Wake-Up taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Shower Tap Wake-Up, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Shower Tap Wake-Up in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '91ba6954-4f03-4d1c-83aa-8a90bf1a314f';

-- [Vocal Warm-Ups] Arm Overhead Swaps
UPDATE activities
SET activity = 'Arm Overhead Swaps',
    time = 3,
    description = '<p>Start the session with Arm Overhead Swaps to wake the body. Raise one arm over your head, one hand on hip, then swap over getting gradually faster.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Raise one arm over your head, one hand on hip, then swap over getting gradually faster.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Arm Overhead Swaps, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Arm Overhead Swaps in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '5793247b-c615-4394-ab0b-a6896d84d990';

-- [Vocal Warm-Ups] Apple Chin Head Turns
UPDATE activities
SET activity = 'Apple Chin Head Turns',
    time = 3,
    description = '<p>Start the session with Apple Chin Head Turns to wake the body. Turn head to left, right, back to the centre and down, as if holding a small apple between your chin and chest, returning head to its central….</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Turn head to left, right, back to the centre and down, as if holding a small apple between your chin and chest, returning head to its central position.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Apple Chin Head Turns, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Apple Chin Head Turns in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'e77261e7-6a04-4d3e-b47f-d3be5d1f6b0a';

-- [Vocal Warm-Ups] Fingers Ten and Five
UPDATE activities
SET activity = 'Fingers Ten and Five',
    time = 3,
    description = '<p>Start the session with Fingers Ten and Five to wake the body. Hold out both hands with fingers spread – explain that when I call out ''10'', this is what they show.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Hold out both hands with fingers spread – explain that when I call out ''10'', this is what they show.</li><li>When ''5'' is called out they spread the fingers of one hand out whilst making a fist with the other hand.</li><li>When ''nothing'' is called out they make a fist with both hands.</li><li>Add ''a different 5'' &amp; ''Faster''.</li><li>Then add ''Wiggle your 10'', ''Wave your `10'', ''Shake your 10'', ''Flick your 10'', ''Clasp together and squeeze'', ''Turn them inside out'', ''Stretch them up to the ceiling'', ''Let go''.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Fingers Ten and Five taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Fingers Ten and Five, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>After Fingers Ten and Five, shake out once, then find ‘singer’s feet’ before the first note.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '0f5c345f-a0cb-4a41-bcff-14c29cfc621c';

-- [Vocal Warm-Ups] Shoulder Swimming
UPDATE activities
SET activity = 'Shoulder Swimming',
    time = 3,
    description = '<p>Start the session with Shoulder Swimming to wake the body. Find a good standing position and lift up one shoulder then two.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Find a good standing position and lift up one shoulder then two.</li><li>Take their shoulders swimming, doing the front crawl, back stroke and butterfly strokes!</li></ol><p><strong>Teacher tips</strong></p><ul><li>Model the Shoulder Swimming posture check once, then let pairs self-check: ears over shoulders, soft knees.</li><li>During Shoulder Swimming, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Shoulder Swimming in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '7b1ba2fe-19c1-47fb-ad0e-fce7f6abc826';

-- [Vocal Warm-Ups] Inflatable Ring Breathing
UPDATE activities
SET activity = 'Inflatable Ring Breathing',
    time = 2,
    description = '<p>Use Inflatable Ring Breathing to settle breath and posture before singing. Pretend you are wearing a great big inflatable rubber ring all the way around your middle.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Calms the class and focuses listening before repertoire</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Pretend you are wearing a great big inflatable rubber ring all the way around your middle.</li><li>What you''re going to do is to push the ring out as you breathe in over the count of 4 without making a single noise.</li><li>Then breathe out very quietly over a count of 4.</li><li>Keep the shoulders completely relaxed and down.</li><li>Your lungs will work without you having to use your shoulders.</li></ol><p><strong>Teacher tips</strong></p><ul><li>In Inflatable Ring Breathing, cue ‘fill from the bottom’ and watch shoulders: if they lift, mime pushing the ring/balloon lower.</li><li>In Inflatable Ring Breathing, pause after the first full cycle and ask one pupil what they felt move — name that sensation.</li><li>Repeat Inflatable Ring Breathing once seated if standing posture collapsed — compare the two sensations.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = 'b30e2e3d-16b3-41d4-9905-22778bdb4a74';

-- [Vocal Warm-Ups] Hands Under Rib Cage
UPDATE activities
SET activity = 'Hands Under Rib Cage',
    time = 2,
    description = '<p>Use Hands Under Rib Cage to settle breath and posture before singing. Place your hands underneath your rib cage, breathe in and out in your own time but try to get the sensation of breathing under where your hands are.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Links posture and breathing muscles for clearer tone</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Place your hands underneath your rib cage, breathe in and out in your own time but try to get the sensation of breathing under where your hands are.</li><li>Try to breathe deeply.</li><li>Repeat but with their hands together as in prayer.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Hands Under Rib Cage, hands on ribs/tummy stay light — expansion should be sideways/forwards, not a heaved chest.</li><li>In Hands Under Rib Cage, pause after the first full cycle and ask one pupil what they felt move — name that sensation.</li><li>After Hands Under Rib Cage, ask ‘where did the air go?’ and point to ribs/tummy before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = 'fd1c0c4b-eefb-469b-b78c-da2d67bb9fa4';

-- [Vocal Warm-Ups] Finger Candles
UPDATE activities
SET activity = 'Finger Candles',
    time = 2,
    description = '<p>Use Finger Candles to settle breath and posture before singing. Hold out one hand in front of you, palm facing towards you.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Practises controlled release of air without strain</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Hold out one hand in front of you, palm facing towards you.</li><li>Imagine that each finger is a candle.</li><li>Blow out each candle in turn and then on the last candle blow out any remaining breath.</li><li>Repeat with the other hand under your belly button.</li><li>Repeat with the following sounds: ff; ff ff ff ff ; ssh ssh ssh ssh ssh.</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Finger Candles, keep the imaginary flame small — if air blasts, reset to a gentle stream on one finger.</li><li>During Finger Candles, hands on ribs/tummy stay light — expansion should be sideways/forwards, not a heaved chest.</li><li>Keep the airflow in Finger Candles quiet and even; stop if throats tighten and rematch on a softer ‘sss’.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = '3d38312f-71bd-4419-a449-f18170c1c557';

-- [Vocal Warm-Ups] Ssh Shower Countdowns
UPDATE activities
SET activity = 'Ssh Shower Countdowns',
    time = 2,
    description = '<p>Use Ssh Shower Countdowns to settle breath and posture before singing. Say ''Ssh, ssh, ssh, sshhhhh'' in rhythm.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Practises controlled release of air without strain</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Say ''Ssh, ssh, ssh, sshhhhh'' in rhythm.</li><li>Then incorporate it giving yourself a shower.</li><li>Set the challenge of while the water is running down – you''re going to be the water going down using the ''Ssh'' sound over a count of 4.</li><li>You have that count of 4 to wash all over and then return to rubbing your hands in front of you.</li><li>Then repeat it over a count of 3.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep the airflow in Ssh Shower Countdowns quiet and even; stop if throats tighten and rematch on a softer ‘sss’.</li><li>In Ssh Shower Countdowns, pause after the first full cycle and ask one pupil what they felt move — name that sensation.</li><li>After Ssh Shower Countdowns, ask ‘where did the air go?’ and point to ribs/tummy before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = '13429fb2-e801-4f73-ada6-b0d2bfe8a041';

-- [Vocal Warm-Ups] Single Flame Puffs
UPDATE activities
SET activity = 'Single Flame Puffs',
    time = 2,
    description = '<p>Use Single Flame Puffs to settle breath and posture before singing. Stretch one arm out in front of them with one finger pointing up, imagining there is a flame on the end of it.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Practises controlled release of air without strain</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Stretch one arm out in front of them with one finger pointing up, imagining there is a flame on the end of it.</li><li>Without bending towards it they are to try and blow it out with short puffs.</li><li>Can they feel the air on their finger and their diaphragm muscle working?</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Single Flame Puffs, keep the imaginary flame small — if air blasts, reset to a gentle stream on one finger.</li><li>During Single Flame Puffs, hands on ribs/tummy stay light — expansion should be sideways/forwards, not a heaved chest.</li><li>After Single Flame Puffs, ask ‘where did the air go?’ and point to ribs/tummy before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = 'fadfc595-a16c-4368-a217-5cbf43c46018';

-- [Vocal Warm-Ups] Lip Roll Horse
UPDATE activities
SET activity = 'Lip Roll Horse',
    time = 2,
    description = '<p>Warm the face and diction with Lip Roll Horse. Make your lips very loose and floppy and do a lip-roll to a ''p'' sound, like a horse.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Loosens lips for freer onset and buzz</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Make your lips very loose and floppy and do a lip-roll to a ''p'' sound, like a horse.</li><li>Repeat to a rolled ''r''.</li></ol><p><strong>Teacher tips</strong></p><ul><li>If the lip buzz in Lip Roll Horse won’t start, add a tiny voiced ‘b’ or ‘v’ underneath — never force dry lips.</li><li>For Lip Roll Horse, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>After Lip Roll Horse, spot one consonant that still smudges and drill only that word.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Raise the tempo or move the pattern up by semitones while keeping every consonant.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = '06b55693-2e61-4ef3-8697-cc73ca8d6036';

-- [Vocal Warm-Ups] Chew Toffee Face Loosen
UPDATE activities
SET activity = 'Chew Toffee Face Loosen',
    time = 2,
    description = '<p>Warm the face and diction with Chew Toffee Face Loosen. Loosen the face by imagining they are chewing a great big toffee.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Makes warm-up playful so diction feels low-stakes</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Loosen the face by imagining they are chewing a great big toffee.</li><li>Squeeze the eyes together as if squinting from the sun then blow the cheeks out.</li><li>Then chew a bit more and repeat.</li></ol><p><strong>Teacher tips</strong></p><ul><li>In Chew Toffee Face Loosen, keep the chew huge and silent for two beats before adding voice — floppy face, not clenched jaw.</li><li>For Chew Toffee Face Loosen, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>Land Chew Toffee Face Loosen on a whispered clear sentence, then the same sentence sung.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = '274205bd-b76c-4f2b-8ada-cdc9784530e0';

-- [Vocal Warm-Ups] Diction Sentence
UPDATE activities
SET activity = 'Diction Sentence',
    time = 2,
    description = '<p>Warm the face and diction with Diction Sentence. Say the words ''Diction is done with the tip of the tongue and the teeth.''.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Strengthens tongue agility for consonants</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Say the words ''Diction is done with the tip of the tongue and the teeth.''.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Diction Sentence, exaggerate tip-of-tongue consonants slowly first; only speed up when every syllable stays clear.</li><li>For Diction Sentence, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>After Diction Sentence, spot one consonant that still smudges and drill only that word.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = 'b337a6c0-082f-416a-94a4-aba1a626236f';

-- [Vocal Warm-Ups] Shabba Doo Chant
UPDATE activities
SET activity = 'Shabba Doo Chant',
    time = 2,
    description = '<p>Warm the face and diction with Shabba Doo Chant. Chant the scat words – ''Shabba doo dabba doo, dibba doo dabba doo, dibba doo dabba doo, dibba doo day''.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Makes warm-up playful so diction feels low-stakes</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Chant the scat words – ''Shabba doo dabba doo, dibba doo dabba doo, dibba doo dabba doo, dibba doo day''.</li><li>Learn a phrase at a time then put two phrases together with a count of 4 after both before repeating them.</li><li>Then practise the last two phrases separately before putting the whole chant together.</li><li>Then sing it on 2 notes a 5th apart starting with the higher note.</li><li>Move onto the other note after the 1st syllable of the next phrase.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Teach one Shabba Doo Chant phrase call-and-response before chaining; clap a pulse underneath so timing stays shared.</li><li>For Shabba Doo Chant, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>Land Shabba Doo Chant on a whispered clear sentence, then the same sentence sung.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = '926ef737-5af5-4467-a111-84dd76d03469';

-- [Vocal Warm-Ups] Mama Made Me Mash M'n'M's
UPDATE activities
SET activity = 'Mama Made Me Mash M''n''M''s',
    time = 2,
    description = '<p>Warm the face and diction with Mama Made Me Mash M''n''M''s. Sing the phrase ''Mama made me mash my m''n''m''s'' on a monotone gradually rising in pitch up a scale.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Makes warm-up playful so diction feels low-stakes</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Sing the phrase ''Mama made me mash my m''n''m''s'' on a monotone gradually rising in pitch up a scale.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Mama Made Me Mash M''n''M''s; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>For Mama Made Me Mash M''n''M''s, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>Land Mama Made Me Mash M''n''M''s on a whispered clear sentence, then the same sentence sung.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = '21bda8bf-c2ea-49e3-ae24-93ecd5cb6c5c';

-- [Vocal Warm-Ups] Sing Ng Siren
UPDATE activities
SET activity = 'Sing Ng Siren',
    time = 3,
    description = '<p>Explore pitch and listening with Sing Ng Siren. Sirening is the best vocal warm-up technique.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sirening is the best vocal warm-up technique.</li><li>Say ''Sing'' and hold the ''ng'' sound.</li><li>Aiming for no air and not very much volume so that you''re not pushing too much.</li><li>Sing a sustained sound on one note first then travel up and down the vocal range on this sound as quietly as you can.</li><li>The sound should be entirely produced out of the nose, not the mouth, so the resonance is in the nose.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Aim for a continuous buzz in Sing Ng Siren with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>On Sing Ng Siren, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After Sing Ng Siren, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'f395f9b3-c15a-4768-ad09-1c1d5f795e36';

-- [Vocal Warm-Ups] Laughing Ng Hand Follow
UPDATE activities
SET activity = 'Laughing Ng Hand Follow',
    time = 3,
    description = '<p>Explore pitch and listening with Laughing Ng Hand Follow. Say the word ''laughing'' and then hold on to the ''ng'' whilst following the conductors hand direction moving up and down.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Say the word ''laughing'' and then hold on to the ''ng'' whilst following the conductors hand direction moving up and down.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Aim for a continuous buzz in Laughing Ng Hand Follow with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>In Laughing Ng Hand Follow, the leader’s hand must move smoothly — practise the gesture silently once so voices don’t jump.</li><li>Keep theatrical laughs in Laughing Ng Hand Follow supported from the middle — fun, not scraped from the throat.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'cdc90dd3-8884-497a-8c75-c195a888cf9c';

-- [Vocal Warm-Ups] Draw an Animal on Ng
UPDATE activities
SET activity = 'Draw an Animal on Ng',
    time = 3,
    description = '<p>Explore pitch and listening with Draw an Animal on Ng. Think of an animal to draw in the air.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Think of an animal to draw in the air.</li><li>Sing the word ''sing'', holding onto the ''ng'' whilst drawing this animal.</li><li>Pitch to rise and fall with their pencil.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Aim for a continuous buzz in Draw an Animal on Ng with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>Keep drawn shapes in Draw an Animal on Ng large and slow so pitch can travel; switch animals only when the buzz stays connected.</li><li>After Draw an Animal on Ng, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '9d4e54e3-f1b1-4265-8a5c-21531a4c72c1';

-- [Vocal Warm-Ups] Mm Head Resonance Hum
UPDATE activities
SET activity = 'Mm Head Resonance Hum',
    time = 3,
    description = '<p>Explore pitch and listening with Mm Head Resonance Hum. Begin by humming ''mm'' on any pitch.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Begin by humming ''mm'' on any pitch.</li><li>Drop the jaw slightly and ensure lips are relaxed and floppy, so the whole head ''rings''.</li><li>Next say the word ''sing'' and hold the ''ng'' sound with the mouth slightly open.</li><li>The feeling is like a laser beam coming out of the top of the head.</li><li>Breathing should be relaxed and the sound full but not forced.</li></ol><p><strong>Teacher tips</strong></p><ul><li>If the lip buzz in Mm Head Resonance Hum won’t start, add a tiny voiced ‘b’ or ‘v’ underneath — never force dry lips.</li><li>Aim for a continuous buzz in Mm Head Resonance Hum with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>After Mm Head Resonance Hum, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'abbd400b-9132-491a-ae81-7390aea8567d';

-- [Vocal Warm-Ups] Whoah Voice Juggling
UPDATE activities
SET activity = 'Whoah Voice Juggling',
    time = 3,
    description = '<p>Explore pitch and listening with Whoah Voice Juggling. Juggling with your voice (like sirening) but to a ''Whoah'' sound.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Juggling with your voice (like sirening) but to a ''Whoah'' sound.</li><li>Follow the conductors hand for the pitch direction.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Aim for a continuous buzz in Whoah Voice Juggling with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>In Whoah Voice Juggling, the leader’s hand must move smoothly — practise the gesture silently once so voices don’t jump.</li><li>Finish Whoah Voice Juggling descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '1752075c-cca2-4c71-8408-a98b89631fb5';

-- [Vocal Warm-Ups] John Kanaka
UPDATE activities
SET activity = 'John Kanaka',
    time = 5,
    description = '<p>Use John Kanaka as a lively call-and-response sea shanty warm-up. Keep the ‘Hoo!’ / refrain crisp and the beat steady.</p><p><strong>Why it works</strong></p><ul><li>Warms group singing with strong shared pulse</li><li>Builds call-and-response listening</li><li>Lifts energy before repertoire</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle with space to move arms. Whole class. No props needed. About 5 minutes.</p><p><strong>How to do it</strong></p><ol><li>I thought I heard the old man say (hoo!) (John, Kanaka-naka, too-rye-ay) Today, today it''s a holiday (hoo!) (John, Kanaka-naka, too-rye-ay) Too-rye-ay, oh!</li><li>Too-rye-ay John, Kanaka-naka, too-rye-ay We''re bound away at the break of day (hoo!) (John, Kanaka-naka, too-rye-ay) We''re bound away for ''Frisco Bay (hoo!) (John, Kanaka-naka, too-rye-ay) Too-rye-ay, oh!</li><li>Too-rye-ay John, Kanaka-naka, too-rye-ay Them Frisco girls ain''t got no comb (hoo!) (John, Kanaka-naka, too-rye-ay) They comb their hair with a herring backbone (hoo!) (John, Kanaka-naka, too-rye-ay) Too-rye-ay, oh!</li><li>Too-rye-ay John, Kanaka-naka, too-rye-ay Just one more heave and that''ll do (hoo!) (John, Kanaka-naka, too-rye-ay) ''Cause we''re the crew to pull her through (hoo!) (John, Kanaka-naka, too-rye-ay) Too-rye-ay, oh!</li><li>Too-rye-ay John, Kanaka-naka, too-rye-ay I thought I heard the old man say (hoo!) (John, Kanaka-naka, too-rye-ay) Today, today it''s a holiday (hoo!) (John, Kanaka-naka, too-rye-ay) Too-rye-ay, oh!</li></ol><p><strong>Teacher tips</strong></p><ul><li>Teach the refrain first so every ‘John Kanaka-naka too-rye-ay’ lands together.</li><li>Keep the ‘Hoo!’ short and supported — no shouted throat sound.</li><li>If words tangle, speak one verse in rhythm before singing.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'be8fad48-65a8-449a-945d-92783b90158c';

-- [Physical Starters] Shake Hands Chant
UPDATE activities
SET activity = 'Shake Hands Chant',
    time = 3,
    description = '<p>Start the session with Shake Hands Chant to wake the body. Shake hands up in the air as you chant ‘And an up, shake, shake, shake, shakedy shake’, ‘and a down shake, shake, shake, shakedy shake’ with the….</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Shake hands up in the air as you chant ‘And an up, shake, shake, shake, shakedy shake’, ‘and a down shake, shake, shake, shakedy shake’ with the appropriate actions.</li><li>Repeat twice before ‘To the front, to the back, to the s-s-side’ x2.</li><li>Then ‘Go around and around’ with a stirring type action, as if stirring something in a large cauldron.</li><li>Repeat but getting gradually faster.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Shake Hands Chant taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Shake Hands Chant, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Shake Hands Chant and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'e4ecfd93-27a5-431a-8003-afb7f67d9b1a';

-- [Physical Starters] Rub and Shake Hands
UPDATE activities
SET activity = 'Rub and Shake Hands',
    time = 3,
    description = '<p>Start the session with Rub and Shake Hands to wake the body. Rub hands together, shake hands out and in and up and down.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Rub hands together, shake hands out and in and up and down.</li><li>Mix the order up.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Rub and Shake Hands taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Rub and Shake Hands, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Rub and Shake Hands in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Add an opposite pattern or faster swap on a shared cue.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'e71c92f1-0efa-41a2-84bc-6ce4a9357319';

-- [Physical Starters] Side Bend Stretch
UPDATE activities
SET activity = 'Side Bend Stretch',
    time = 3,
    description = '<p>Start the session with Side Bend Stretch to wake the body. Put feet together and raise arms in a v-shape above the head.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Put feet together and raise arms in a v-shape above the head.</li><li>Bend over to the right then to the left which will help to stretch singing muscles.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Side Bend Stretch, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Side Bend Stretch in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '44219639-cb49-4b2b-a29b-2c81e58e577d';

-- [Physical Starters] Posture Check
UPDATE activities
SET activity = 'Posture Check',
    time = 3,
    description = '<p>Start the session with Posture Check to wake the body. Check posture by making sure that ears are over shoulders.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Check posture by making sure that ears are over shoulders.</li><li>Shoulders are over hips and hips are over ankles.</li><li>Stretch both hands up into the air so that the rib cage is opened up.</li><li>As the arms are lowered, try to keep the same openness in the rib cage.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Posture Check, hands on ribs/tummy stay light — expansion should be sideways/forwards, not a heaved chest.</li><li>Model the Posture Check posture check once, then let pairs self-check: ears over shoulders, soft knees.</li><li>After Posture Check, shake out once, then find ‘singer’s feet’ before the first note.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'ba24adfa-5f69-4dee-a58b-adac76f7156a';

-- [Physical Starters] My Bonny B/O Game
UPDATE activities
SET activity = 'My Bonny B/O Game',
    time = 3,
    description = '<p>Start the session with My Bonny B/O Game to wake the body. Sing ‘My bonny lies over the ocean’, standing up and sitting down each time a word is sung that begins with the letter B.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sing ‘My bonny lies over the ocean’, standing up and sitting down each time a word is sung that begins with the letter B.</li><li>Then add a clap on every word which contains the letter ‘O’.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Spot every B in My Bonny B/O Game spoken once, then sing; celebrate clean sit/stand changes without collapsing posture.</li><li>During My Bonny B/O Game, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of My Bonny B/O Game and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '6bc89369-dc53-4dc3-ab63-0f1d212b9f23';

-- [Physical Starters] Shower Tap Wake-Up
UPDATE activities
SET activity = 'Shower Tap Wake-Up',
    time = 3,
    description = '<p>Start the session with Shower Tap Wake-Up to wake the body. Imagine you are having a bit of a shower – quickly tap with both hands up your legs, along both arms, down your front etc.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Imagine you are having a bit of a shower – quickly tap with both hands up your legs, along both arms, down your front etc.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Shower Tap Wake-Up taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Shower Tap Wake-Up, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Shower Tap Wake-Up in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'e31dda3d-16eb-4b6e-9069-e171a826c350';

-- [Physical Starters] Arm Overhead Swaps
UPDATE activities
SET activity = 'Arm Overhead Swaps',
    time = 3,
    description = '<p>Start the session with Arm Overhead Swaps to wake the body. Raise one arm over your head, one hand on hip, then swap over getting gradually faster.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Raise one arm over your head, one hand on hip, then swap over getting gradually faster.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Arm Overhead Swaps, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Arm Overhead Swaps in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'b4326b62-8396-4de1-844e-640a6a0d7a00';

-- [Physical Starters] Apple Chin Head Turns
UPDATE activities
SET activity = 'Apple Chin Head Turns',
    time = 3,
    description = '<p>Start the session with Apple Chin Head Turns to wake the body. Turn head to left, right, back to the centre and down, as if holding a small apple between your chin and chest, returning head to its central….</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Turn head to left, right, back to the centre and down, as if holding a small apple between your chin and chest, returning head to its central position.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Apple Chin Head Turns, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Apple Chin Head Turns in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '35aa5b11-5cae-4311-b3b3-123df880a209';

-- [Physical Starters] 10-5-Nothing Hand Game
UPDATE activities
SET activity = '10-5-Nothing Hand Game',
    time = 3,
    description = '<p>Start the session with 10-5-Nothing Hand Game to wake the body. Hold out both hands with fingers spread – explain that when I call out ‘10’, this is what they show.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Hold out both hands with fingers spread – explain that when I call out ‘10’, this is what they show.</li><li>When ‘5’ is called out they spread the fingers of one hand out whilst making a fist with the other hand.</li><li>When ‘nothing’ is called out they make a fist with both hands.</li><li>Add ‘a different 5’ &amp; ‘Faster’.</li><li>Then add ‘Wiggle your 10’, ‘Wave your `10’, ‘Shake your 10’, ‘Flick your 10’, ‘Clasp together and squeeze’, ‘Turn them inside out’, ‘Stretch them up to the ceiling’, ‘Let go’.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep 10-5-Nothing Hand Game taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During 10-5-Nothing Hand Game, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End 10-5-Nothing Hand Game in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '06ca027f-4558-42c3-a8d3-9bf615807647';

-- [Physical Starters] Shoulder Swimming
UPDATE activities
SET activity = 'Shoulder Swimming',
    time = 3,
    description = '<p>Start the session with Shoulder Swimming to wake the body. Find a good standing position and lift up one shoulder then two.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Find a good standing position and lift up one shoulder then two.</li><li>Take their shoulders swimming, doing the front crawl, back stroke and butterfly strokes!</li></ol><p><strong>Teacher tips</strong></p><ul><li>Model the Shoulder Swimming posture check once, then let pairs self-check: ears over shoulders, soft knees.</li><li>During Shoulder Swimming, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Shoulder Swimming in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '189c0452-b4a7-4d80-a7e1-95db299cd026';

-- [Physical Starters] Drop and Spring Stretch
UPDATE activities
SET activity = 'Drop and Spring Stretch',
    time = 3,
    description = '<p>Start the session with Drop and Spring Stretch to wake the body. Stretch up high to the ceiling and drop hands at the wrists, then drop at the elbows then the shoulders, let the head flop then drop at the hips.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Stretch up high to the ceiling and drop hands at the wrists, then drop at the elbows then the shoulders, let the head flop then drop at the hips.</li><li>Then spring into life.</li><li>Check their body posture is correct.</li><li>Put thumbs under the chin with hands behind the ears and lift the heads.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Model the Drop and Spring Stretch posture check once, then let pairs self-check: ears over shoulders, soft knees.</li><li>During Drop and Spring Stretch, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Drop and Spring Stretch and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '3eb189d8-05ee-40a8-bdf6-80afe4703cde';

-- [Physical Starters] Directional Arm Shake-Out
UPDATE activities
SET activity = 'Directional Arm Shake-Out',
    time = 3,
    description = '<p>Start the session with Directional Arm Shake-Out to wake the body. Raise the arms quickly and then let them drop and shake out either to the right, left, in front, behind, up high, down low.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Raise the arms quickly and then let them drop and shake out either to the right, left, in front, behind, up high, down low.</li><li>Have one arm doing one thing and the other something different!</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Directional Arm Shake-Out taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Directional Arm Shake-Out, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>After Directional Arm Shake-Out, shake out once, then find ‘singer’s feet’ before the first note.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'e3f77f0c-774d-4dad-b032-8b86d84e3a8e';

-- [Physical Starters] Fruit Face
UPDATE activities
SET activity = 'Fruit Face',
    time = 3,
    description = '<p>Start the session with Fruit Face to wake the body. Play ‘Fruit Face’ where they make their faces as big as possible when ‘Big pumpkin face’ is called out and then they screw up their face, making it….</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Play ‘Fruit Face’ where they make their faces as big as possible when ‘Big pumpkin face’ is called out and then they screw up their face, making it as small as possible on ‘Tiny little raison face’.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Fruit Face, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Fruit Face in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'c4d3f4bb-08d8-4346-903a-33c01e92fb85';

-- [Physical Starters] Full Body Shake-Out
UPDATE activities
SET activity = 'Full Body Shake-Out',
    time = 3,
    description = '<p>Start the session with Full Body Shake-Out to wake the body. Shake out fingers, hands, wrists, elbows, shoulders, middles, hips, ankles, feet.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Shake out fingers, hands, wrists, elbows, shoulders, middles, hips, ankles, feet.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Full Body Shake-Out taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Full Body Shake-Out, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>After Full Body Shake-Out, shake out once, then find ‘singer’s feet’ before the first note.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'f1577294-d5fa-460a-b3c6-a4c13d0268ce';

-- [Physical Starters] Show Me Emotions
UPDATE activities
SET activity = 'Show Me Emotions',
    time = 3,
    description = '<p>Start the session with Show Me Emotions to wake the body. Put their hands in front of their face.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Put their hands in front of their face.</li><li>On the command ‘Show me’ call out an emotion or feeling which they then have to show with their faces – hands apart eg. surprised, happy, worried, excited, angry, proud, sad, delighted.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Show Me Emotions, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Show Me Emotions and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'cdc67f2f-4607-4eee-b518-9cb6a8fbe2e7';

-- [Physical Starters] 4-Count Tap and Shake
UPDATE activities
SET activity = '4-Count Tap and Shake',
    time = 3,
    description = '<p>Start the session with 4-Count Tap and Shake to wake the body. Tap their head 4 times then shake hands out 4 times, tap shoulders 4 times, shake out for 4, tap elbows 4 times, shake out for 4, tap hips 4 times,….</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Tap their head 4 times then shake hands out 4 times, tap shoulders 4 times, shake out for 4, tap elbows 4 times, shake out for 4, tap hips 4 times, shake out, tap knees 4 times, shake out, tap toes 4 times, shake out.</li><li>Repeat the sequence but halve it.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep 4-Count Tap and Shake taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During 4-Count Tap and Shake, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End 4-Count Tap and Shake in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Add an opposite pattern or faster swap on a shared cue.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '483626dc-f182-496f-b662-924a27cb43e5';

-- [Physical Starters] Shoulder Lift and Aaah
UPDATE activities
SET activity = 'Shoulder Lift and Aaah',
    time = 3,
    description = '<p>Start the session with Shoulder Lift and Aaah to wake the body. Bring the shoulders up to the ears as you breathe in and give a big ‘Aaah’ as the shoulders are released.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Bring the shoulders up to the ears as you breathe in and give a big ‘Aaah’ as the shoulders are released.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Shoulder Lift and Aaah, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Shoulder Lift and Aaah and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'ffd46e48-aab8-44db-b703-f29fb1c9912d';

-- [Physical Starters] Banana and Prune
UPDATE activities
SET activity = 'Banana and Prune',
    time = 3,
    description = '<p>Start the session with Banana and Prune to wake the body. Say ‘banana’ with an ‘a’ sound and with lips in a smile.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Say ‘banana’ with an ‘a’ sound and with lips in a smile.</li><li>Say ‘prune’, pushing your lips forward.</li></ol><p><strong>Teacher tips</strong></p><ul><li>If the lip buzz in Banana and Prune won’t start, add a tiny voiced ‘b’ or ‘v’ underneath — never force dry lips.</li><li>During Banana and Prune, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Banana and Prune in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '2d6fb1ca-e0c4-4ad3-bf4d-cebff7cdcdb6';

-- [Physical Starters] Chew and Face Massage
UPDATE activities
SET activity = 'Chew and Face Massage',
    time = 3,
    description = '<p>Start the session with Chew and Face Massage to wake the body. Have a chew, really noisy, one of those chews you get told off for.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Have a chew, really noisy, one of those chews you get told off for.</li><li>Then make it really small in the front of your mouth, like a little rabbit on a carrot.</li><li>Then massage the face, keep it floppy, getting rid of any tension.</li></ol><p><strong>Teacher tips</strong></p><ul><li>In Chew and Face Massage, keep the chew huge and silent for two beats before adding voice — floppy face, not clenched jaw.</li><li>During Chew and Face Massage, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Chew and Face Massage in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'd2dfd4b0-4ac6-42bd-a24c-0ed9bfc3f641';

-- [Physical Starters] Face Squash Brrr
UPDATE activities
SET activity = 'Face Squash Brrr',
    time = 3,
    description = '<p>Start the session with Face Squash Brrr to wake the body. Squash your face together with your hands and go ‘Brrrrr’.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Squash your face together with your hands and go ‘Brrrrr’.</li><li>Then add some sound to the ‘Brrr’ by sliding up and down in pitch.</li><li>Don’t forget the eyebrows as the pitch rises.</li></ol><p><strong>Teacher tips</strong></p><ul><li>If the lip buzz in Face Squash Brrr won’t start, add a tiny voiced ‘b’ or ‘v’ underneath — never force dry lips.</li><li>During Face Squash Brrr, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>After Face Squash Brrr, shake out once, then find ‘singer’s feet’ before the first note.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'b3c3cfb7-183c-477f-a76c-bcfd9ceaeabb';

