-- [Physical Starters] Full Stretch Sequence
UPDATE activities
SET activity = 'Full Stretch Sequence',
    time = 3,
    description = '<p>Start the session with Full Stretch Sequence to wake the body. Stretch up as high as possible with hands, fingers to the ceiling.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Stretch up as high as possible with hands, fingers to the ceiling.</li><li>Drop as low as possible and touch the floor, slowly uncurl to upright and stretch up high as possible.</li><li>Shake out hands and repeat.</li><li>Stretch out arms in front as far as they can then above their head, open them up and return to by their sides.</li><li>Hands by the sides, move the right arm down their right side as far as possible and return upright.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Full Stretch Sequence taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Full Stretch Sequence, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Full Stretch Sequence in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '9d0193b5-d7a4-466b-9791-5333175845f8';

-- [Physical Starters] Rib Cage Lift
UPDATE activities
SET activity = 'Rib Cage Lift',
    time = 3,
    description = '<p>Start the session with Rib Cage Lift to wake the body. Lift their arms above the head which raises the rib cage.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Lift their arms above the head which raises the rib cage.</li><li>As they bring their arms down think about keeping their rib-cage up high.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Rib Cage Lift, hands on ribs/tummy stay light — expansion should be sideways/forwards, not a heaved chest.</li><li>During Rib Cage Lift, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Rib Cage Lift in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '6068be5e-ce8e-49e9-b02d-22156050580a';

-- [Physical Starters] DIY Acupressure
UPDATE activities
SET activity = 'DIY Acupressure',
    time = 3,
    description = '<p>Start the session with DIY Acupressure to wake the body. DIY acupressure: Make your hands into fists, like little hammers, and stimulate the skin by gently tapping all over your body.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>DIY acupressure: Make your hands into fists, like little hammers, and stimulate the skin by gently tapping all over your body.</li><li>Start with the arms, shoulders and hands, then move to the chest and tummy, legs.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During DIY Acupressure, hands on ribs/tummy stay light — expansion should be sideways/forwards, not a heaved chest.</li><li>During DIY Acupressure, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>After DIY Acupressure, shake out once, then find ‘singer’s feet’ before the first note.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '9fd05b24-a023-4756-ab6e-ebc9e0b294c1';

-- [Physical Starters] Head Pencil Circles
UPDATE activities
SET activity = 'Head Pencil Circles',
    time = 3,
    description = '<p>Start the session with Head Pencil Circles to wake the body. Imagine a pencil on the top of your head and you are drawing a dinner plate with it.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Imagine a pencil on the top of your head and you are drawing a dinner plate with it.</li><li>How big can you make it before losing your balance?</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Head Pencil Circles, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Head Pencil Circles in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
