-- [Physical Starters] Cross-Body Knee Taps
UPDATE activities
SET activity = 'Cross-Body Knee Taps',
    time = 3,
    description = '<p>Start the session with Cross-Body Knee Taps to wake the body. To a beat, have the RH tap the LK raised and then alternate so LH is tapping the RK x2.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>To a beat, have the RH tap the LK raised and then alternate so LH is tapping the RK x2.</li><li>Then tap the LL with the RH behind the body and then the RL with the LH behind x2.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Cross-Body Knee Taps taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Cross-Body Knee Taps, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Cross-Body Knee Taps in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '2cd549a0-edcf-443c-b682-a80a9e7b5f46';

-- [Physical Starters] Hip Whisks
UPDATE activities
SET activity = 'Hip Whisks',
    time = 3,
    description = '<p>Start the session with Hip Whisks to wake the body. Make whisk-like movements with their middles (hips), keeping the feet still.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Make whisk-like movements with their middles (hips), keeping the feet still.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Hip Whisks, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Hip Whisks in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '4e1b0c62-37a0-43f4-9fdc-12524d06280f';

-- [Physical Starters] Magic Hammers
UPDATE activities
SET activity = 'Magic Hammers',
    time = 3,
    description = '<p>Start the session with Magic Hammers to wake the body. ‘Magic hammers’: Each person should imagine they have two ‘magic hammers’, one in each hand.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>‘Magic hammers’: Each person should imagine they have two ‘magic hammers’, one in each hand.</li><li>Imagine 4 sets of nails in front of them: one at head height, one at chest height, one at hip height and one at their feet.</li><li>The aim is to bang in the nails using the magic hammers as fast as possible.</li><li>Choose the number of times it will take to hammer in the initial set of nails eg. 5 movements.</li><li>To perform the set, you have to hammer in the nails at each level as fast as possible, counting each movement out loud as you go.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Magic Hammers taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Magic Hammers, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Magic Hammers in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '9c007b3b-685f-43f3-99bc-cd794427fd20';

-- [Physical Starters] Loose Limbs Shake
UPDATE activities
SET activity = 'Loose Limbs Shake',
    time = 3,
    description = '<p>Start the session with Loose Limbs Shake to wake the body. Give yourself a shake.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Give yourself a shake.</li><li>Imagine you have no control over your arms but they are just two things stuck on the side of your body.</li><li>Get a leg involved as well.</li><li>Then give everything in the middle a little wiggle.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Loose Limbs Shake taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Loose Limbs Shake, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>After Loose Limbs Shake, shake out once, then find ‘singer’s feet’ before the first note.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '27104523-754c-4c2d-80a9-1cf96f0f0118';

-- [Physical Starters] Big Body Small Body
UPDATE activities
SET activity = 'Big Body Small Body',
    time = 3,
    description = '<p>Start the session with Big Body Small Body to wake the body. After 3, make yourself and your body as big as they can be.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>After 3, make yourself and your body as big as they can be.</li><li>Eyebrows are really important when singing, you do a lot with your eyebrows, so getting them raised is really important.</li><li>Then go really small face, small body, very tense and screw your face up.</li><li>Alternate between the two and then smile with a terrifying smile.</li><li>All teeth and no sincerity!</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Big Body Small Body, exaggerate tip-of-tongue consonants slowly first; only speed up when every syllable stays clear.</li><li>During Big Body Small Body, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Big Body Small Body in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '6ccaa03d-6d9f-4193-b4de-4b62d08266da';

-- [Physical Starters] Horse Ride Warm-Up
UPDATE activities
SET activity = 'Horse Ride Warm-Up',
    time = 3,
    description = '<p>Start the session with Horse Ride Warm-Up to wake the body. Imagine they are taking a horse out for a ride.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Imagine they are taking a horse out for a ride.</li><li>Have hands up in front of them as if holding the reins.</li><li>Take your horse for a trot first, then change to a canter, then a gallop.</li><li>Then when I stop you go ‘Whooah’.</li></ol><p><strong>Teacher tips</strong></p><ul><li>If the lip buzz in Horse Ride Warm-Up won’t start, add a tiny voiced ‘b’ or ‘v’ underneath — never force dry lips.</li><li>During Horse Ride Warm-Up, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Horse Ride Warm-Up in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '477070b9-1641-46fa-95cd-e4b1ccc68680';

-- [Physical Starters] Upper Chest Width
UPDATE activities
SET activity = 'Upper Chest Width',
    time = 3,
    description = '<p>Start the session with Upper Chest Width to wake the body. Emphasise the width of the upper chest, draw a line from one shoulder to the other making it as long as possible.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Emphasise the width of the upper chest, draw a line from one shoulder to the other making it as long as possible.</li><li>Make sure there is no tension in the shoulders or neck.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Upper Chest Width, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>After Upper Chest Width, shake out once, then find ‘singer’s feet’ before the first note.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '5883cbc0-d827-4a07-923e-a2aaf13de117';

-- [Physical Starters] Walk and Stretch Counts
UPDATE activities
SET activity = 'Walk and Stretch Counts',
    time = 3,
    description = '<p>Start the session with Walk and Stretch Counts to wake the body. Walk on the spot to the beat.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Walk on the spot to the beat.</li><li>Call out a number and on the next beat the group stretch their bodies in different ways for the number of beats called, and then continue walking on the spot.</li><li>Use the backing track of a song they are working on.</li><li>Practice a few possible stretch moves before they start.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Walk and Stretch Counts, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Walk and Stretch Counts and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'a7964811-0729-4677-a640-ae80bd6a6854';

-- [Physical Starters] Chocolate Bar Reach
UPDATE activities
SET activity = 'Chocolate Bar Reach',
    time = 3,
    description = '<p>Start the session with Chocolate Bar Reach to wake the body. Stretch up to the ceiling with your right arm as high as you can.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Stretch up to the ceiling with your right arm as high as you can.</li><li>Go up on tiptoes, trying to reach a chocolate bar on the ceiling.</li><li>Let your right arm fall back to your side.</li><li>Repeat with the left arm.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Chocolate Bar Reach, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>After Chocolate Bar Reach, shake out once, then find ‘singer’s feet’ before the first note.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '9529881e-6e67-490b-a2db-65c103a90d99';

-- [Physical Starters] Step and Clap Countdown
UPDATE activities
SET activity = 'Step and Clap Countdown',
    time = 3,
    description = '<p>Start the session with Step and Clap Countdown to wake the body. Step to the right and clap once, repeat to the left, then to the right with two claps, left and clap twice, then step to the right and clap 3 times….</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Step to the right and clap once, repeat to the left, then to the right with two claps, left and clap twice, then step to the right and clap 3 times then to the left, finishing with a swoop up and clap high in the air on the words ‘Let’s Sing’.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Step and Clap Countdown, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Step and Clap Countdown in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '86ae9c9e-47fd-4bf7-8ad4-f6a7a9275175';

-- [Physical Starters] Puppet Hand and Knee
UPDATE activities
SET activity = 'Puppet Hand and Knee',
    time = 3,
    description = '<p>Start the session with Puppet Hand and Knee to wake the body. Stretch out your right hand.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Stretch out your right hand.</li><li>Imagine you are a puppet and there is a string from your right hand attached to your right knee.</li><li>Raise your right hand and bring your right knee up at the same time.</li><li>Repeat with the left hand and knee.</li><li>Then alternate them.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Puppet Hand and Knee, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>After Puppet Hand and Knee, shake out once, then find ‘singer’s feet’ before the first note.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '51fabcff-e12b-4c71-b32c-f6799c7a524d';

-- [Physical Starters] Whacky Numbers
UPDATE activities
SET activity = 'Whacky Numbers',
    time = 3,
    description = '<p>Start the session with Whacky Numbers to wake the body. Play ‘Whacky numbers’.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Play ‘Whacky numbers’.</li><li>Punch the air vigorously 8 times with the RH, then 8 times with the LH, then kick the air 8 times with the RF then 8 times with the LF.</li><li>Count out loud as they perform the actions.</li><li>Repeat the sequence, but halve the numbers, eg 4 times with each hand and foot, then twice, then once.</li><li>Finish the whole sequence by jumping in the air, arms held high in a V-shape and shout ‘Let’s Sing!’ Repeat the cycle again, but this time perform it with a whispering voice.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Whacky Numbers, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Whacky Numbers and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '4a1e05ea-f46f-490c-96d8-ec2dca7b6ee8';

-- [Physical Starters] Head-Shoulders-Hips-Knees-Toes
UPDATE activities
SET activity = 'Head-Shoulders-Hips-Knees-Toes',
    time = 3,
    description = '<p>Start the session with Head-Shoulders-Hips-Knees-Toes to wake the body. Tap the head 8 times, then shoulders, hips, knees &amp; toes.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Tap the head 8 times, then shoulders, hips, knees &amp; toes.</li><li>Repeat 4 times, then twice then once.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Head-Shoulders-Hips-Knees-Toes taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Head-Shoulders-Hips-Knees-Toes, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Head-Shoulders-Hips-Knees-Toes in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Add an opposite pattern or faster swap on a shared cue.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'e928f570-9329-4740-9296-5806f24da9a0';

-- [Physical Starters] Neck and Shoulder Rolls
UPDATE activities
SET activity = 'Neck and Shoulder Rolls',
    time = 3,
    description = '<p>Start the session with Neck and Shoulder Rolls to wake the body. Rotate the neck round slowly.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Rotate the neck round slowly.</li><li>Lift each shoulder up in turn under their ears then both together and turn around.</li><li>Shake out hands.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Neck and Shoulder Rolls taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Neck and Shoulder Rolls, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Neck and Shoulder Rolls and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Add an opposite pattern or faster swap on a shared cue.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'e8a5807a-d5d7-4253-bd5b-9d5be0472f80';

-- [Physical Starters] Head Centre Awareness
UPDATE activities
SET activity = 'Head Centre Awareness',
    time = 3,
    description = '<p>Start the session with Head Centre Awareness to wake the body. Begin with the head facing straight ahead.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Begin with the head facing straight ahead.</li><li>Without straining, turn it to the left, hold, bring back to the middle, repeat this on the right and upwards and downwards.</li><li>Try again with the eyes closed.</li><li>Be aware of your head and establish where your ‘middle’ is by feeling rather than looking.</li><li>Check that chin is not too far up or down.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Head Centre Awareness, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Head Centre Awareness in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'a67516a7-10db-4f15-814c-37f03a1811d0';

-- [Physical Starters] Rubber Chicken
UPDATE activities
SET activity = 'Rubber Chicken',
    time = 3,
    description = '<p>Start the session with Rubber Chicken to wake the body. ‘Rubber Chicken’.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>‘Rubber Chicken’.</li><li>Imagine you have a rubber chicken hanging on to your right hand.</li><li>Try to shake it off counting as you go – 1 2 3 4 5 6 7 8.</li><li>Do the same on your left hand, then right foot, then left foot.</li><li>Repeat the whole process counting to 4, then 2, then 1.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Rubber Chicken taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Rubber Chicken, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Rubber Chicken in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '150698bc-2d89-40e8-a6c4-884a7ac74945';

-- [Physical Starters] Step and Clap to Track
UPDATE activities
SET activity = 'Step and Clap to Track',
    time = 3,
    description = '<p>Start the session with Step and Clap to Track to wake the body. Over a backing track of a song to be sung, eg.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Over a backing track of a song to be sung, eg. gospel style, step and clap to the music.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Step and Clap to Track, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Step and Clap to Track in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '8aaa78a2-3d7e-46f0-869e-5e9f500be216';

-- [Physical Starters] Knee Bounces and Claps
UPDATE activities
SET activity = 'Knee Bounces and Claps',
    time = 3,
    description = '<p>Start the session with Knee Bounces and Claps to wake the body. Practice knee bounces, rising up and down on the feet, springing gently from foot to foot, keeping the knees soft and loose all the time.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Practice knee bounces, rising up and down on the feet, springing gently from foot to foot, keeping the knees soft and loose all the time.</li><li>Add claps in different directions and on different beats.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Knee Bounces and Claps, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>After Knee Bounces and Claps, shake out once, then find ‘singer’s feet’ before the first note.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '1e4a5715-f77e-437d-a8ee-335363317549';

-- [Physical Starters] Slow Hoola Hoop
UPDATE activities
SET activity = 'Slow Hoola Hoop',
    time = 3,
    description = '<p>Start the session with Slow Hoola Hoop to wake the body. Then do a slow-motion hoola hoop in both directions, letting the back sink low.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Then do a slow-motion hoola hoop in both directions, letting the back sink low.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Slow Hoola Hoop, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>After Slow Hoola Hoop, shake out once, then find ‘singer’s feet’ before the first note.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '9ca32203-2aeb-4223-bf08-4bb469f6a15c';

-- [Physical Starters] 4-Beat Huh Pattern
UPDATE activities
SET activity = '4-Beat Huh Pattern',
    time = 3,
    description = '<p>Start the session with 4-Beat Huh Pattern to wake the body. Practice altogether counting in groups of 4.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Practice altogether counting in groups of 4.</li><li>Step a 4 beat cycle, stamping and voicing ‘Huh!’ on the 1st beat.</li><li>Each time they say ‘Huh!’ they are to bring their arms forward with outstretched arms.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During 4-Beat Huh Pattern, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of 4-Beat Huh Pattern and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '72718939-e25b-4559-976c-6942baadae60';

-- [Physical Starters] 3-Beat Ha Pattern
UPDATE activities
SET activity = '3-Beat Ha Pattern',
    time = 3,
    description = '<p>Start the session with 3-Beat Ha Pattern to wake the body. Then do the same thing but with a 3 beat cycle and with the sound ‘Ha!’ Encourage both of these sounds to come from the tummy.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Then do the same thing but with a 3 beat cycle and with the sound ‘Ha!’ Encourage both of these sounds to come from the tummy.</li><li>This group, however, are to throw their arms towards the ceiling with outstretched hands.</li><li>Then allocate one line to the 4 beat pattern and the other to the 3 beat pattern and put both together.</li><li>Count in – ‘1 2 3 4, 1 2 3 go!’ Once practised, the groups can switch over and then move forward towards each other, keeping in line, ending up on the opposite sides of the space.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During 3-Beat Ha Pattern, hands on ribs/tummy stay light — expansion should be sideways/forwards, not a heaved chest.</li><li>During 3-Beat Ha Pattern, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End 3-Beat Ha Pattern in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '18d4d37b-8319-49ff-af8a-b9c75359dd28';

-- [Physical Starters] Shoulders and Fingers Warm-Up
UPDATE activities
SET activity = 'Shoulders and Fingers Warm-Up',
    time = 3,
    description = '<p>Start the session with Shoulders and Fingers Warm-Up to wake the body. Warm up shoulders, individually then both together.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Warm up shoulders, individually then both together.</li><li>Aim to get their ‘east west’ line as wide as possible.</li><li>Stand on their toes then as they come down aim to keep the same height.</li><li>Wiggle fingers, shake out hands, put first finger &amp; thumb together, then 2nd finger &amp; thumb together and so on.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Shoulders and Fingers Warm-Up taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Shoulders and Fingers Warm-Up, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Shoulders and Fingers Warm-Up and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '6f0e3aad-ae7b-4861-8bdb-6fe9b7205bcb';

-- [Physical Starters] High-Low Hand Countdown
UPDATE activities
SET activity = 'High-Low Hand Countdown',
    time = 3,
    description = '<p>Start the session with High-Low Hand Countdown to wake the body. Shake hands out up high 8 times then down low 8 times, then 7 times etc.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Shake hands out up high 8 times then down low 8 times, then 7 times etc. until 1 is reached.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep High-Low Hand Countdown taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During High-Low Hand Countdown, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End High-Low Hand Countdown in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Add an opposite pattern or faster swap on a shared cue.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '6da37782-3834-4d90-b210-e0be6ae183b6';

-- [Physical Starters] Step Clap Call and Response
UPDATE activities
SET activity = 'Step Clap Call and Response',
    time = 3,
    description = '<p>Start the session with Step Clap Call and Response to wake the body. Step to the right and clap then to the left and clap.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Step to the right and clap then to the left and clap.</li><li>Group to then copy vocal sounds in the form of call &amp; response to the rhythm dotted crotchet, dotted crotchet rest: Doom doom.</li><li>Zoom zoom.</li><li>Pah pah.</li><li>Doo bop.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep the airflow in Step Clap Call and Response quiet and even; stop if throats tighten and rematch on a softer ‘sss’.</li><li>During Step Clap Call and Response, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>After Step Clap Call and Response, shake out once, then find ‘singer’s feet’ before the first note.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Add an opposite pattern or faster swap on a shared cue.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'abba0147-86e9-4ce7-b18f-e70cf66f9285';

