-- [Physical Starters] Head Turns
UPDATE activities
SET activity = 'Head Turns',
    time = 3,
    description = '<p>Start the session with Head Turns to wake the body. Head turns: Slowly, while taking deep breaths, turn the head to look left and right.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Head turns: Slowly, while taking deep breaths, turn the head to look left and right.</li><li>Repeat 3 or 4 times.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Head Turns, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Head Turns in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '3366b278-a04c-40c6-99b8-91182f6bcc30';

-- [Physical Starters] Head Tilts
UPDATE activities
SET activity = 'Head Tilts',
    time = 3,
    description = '<p>Start the session with Head Tilts to wake the body. Head tilts: Again, very slowly and while breathing, tilt the head to stretch each side of the neck.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Head tilts: Again, very slowly and while breathing, tilt the head to stretch each side of the neck.</li><li>Never stretch too far – stop before it becomes uncomfortable.</li><li>Repeat 3 or 4 times.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Head Tilts, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Head Tilts in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '247598a9-5b88-4fe8-a512-e922483a6476';

-- [Physical Starters] Shoulders and Upper Back Stretch
UPDATE activities
SET activity = 'Shoulders and Upper Back Stretch',
    time = 3,
    description = '<p>Start the session with Shoulders and Upper Back Stretch to wake the body. Shoulders and upper back: Bring your arms together over your head, hold your hands together and stretch.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Shoulders and upper back: Bring your arms together over your head, hold your hands together and stretch.</li><li>With your elbows straight, reach behind you and stretch your arms.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Shoulders and Upper Back Stretch, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Shoulders and Upper Back Stretch and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'fae293fc-07c2-4087-8692-ffdeed9d025a';

-- [Physical Starters] Pirate Ship Stretch
UPDATE activities
SET activity = 'Pirate Ship Stretch',
    time = 3,
    description = '<p>Start the session with Pirate Ship Stretch to wake the body. Stretch up as if climbing up the side of a pirate ship.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Stretch up as if climbing up the side of a pirate ship.</li><li>Then drop arms down by your sides.</li><li>Chests should be broad and spines elongated.</li><li>Heads should be facing forwards and not pointing up or down.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Pirate Ship Stretch, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Pirate Ship Stretch and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'd6ad844d-30cd-4ebf-8765-50069bf93f52';

-- [Physical Starters] Tall Rib Cage Stretch
UPDATE activities
SET activity = 'Tall Rib Cage Stretch',
    time = 3,
    description = '<p>Start the session with Tall Rib Cage Stretch to wake the body. Reach up high with both arms.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Reach up high with both arms.</li><li>On tiptoe, stretch up and grab an imaginary bar above your head, just out of reach.</li><li>Release the arms and tiptoes but stay ‘up’, maintaining that feeling of relaxed tallness with the rib-cage raised.</li><li>Next, slump forward, so your rib-cage is lowered.</li><li>Breathe in and feel how little space there is for air.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Tall Rib Cage Stretch, hands on ribs/tummy stay light — expansion should be sideways/forwards, not a heaved chest.</li><li>During Tall Rib Cage Stretch, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>After Tall Rib Cage Stretch, shake out once, then find ‘singer’s feet’ before the first note.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '86210449-9f9d-4e16-96ca-e59cd60da048';

-- [Physical Starters] Balance and Rooting
UPDATE activities
SET activity = 'Balance and Rooting',
    time = 3,
    description = '<p>Start the session with Balance and Rooting to wake the body. With eyes shut, lean forward so the weight is transferred slightly too far onto the balls of the feet, then slightly too far back onto the heels.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>With eyes shut, lean forward so the weight is transferred slightly too far onto the balls of the feet, then slightly too far back onto the heels.</li><li>Do the same, side to side.</li><li>Find the optimum balanced position where the weight is divided equally between both.</li><li>Bounce up and down to unlock the knees and feel the weight going into the floor.</li><li>Imagine the legs as screwed into the floor, growing from it like a tree with roots.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Balance and Rooting, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Balance and Rooting and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '58115eda-096a-4c06-8ecd-680ef7cb2fa4';

-- [Physical Starters] Never Lock My Knees
UPDATE activities
SET activity = 'Never Lock My Knees',
    time = 3,
    description = '<p>Start the session with Never Lock My Knees to wake the body. Wiggle the relevant part of the body in turn as you chant.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Wiggle the relevant part of the body in turn as you chant.</li><li>Begin with ‘Oh, I never lock my knees’, in a silly voice to which everyone replies in an identical voice, ‘No, we never lock our knees’.</li><li>Continue with ankles, elbows, shoulders, fingers, hands.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Never Lock My Knees, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Never Lock My Knees in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'cc5d8c95-fc8e-4686-836c-8e91b27bcdcc';

-- [Physical Starters] Shoulder Drop Release
UPDATE activities
SET activity = 'Shoulder Drop Release',
    time = 3,
    description = '<p>Start the session with Shoulder Drop Release to wake the body. Shrug your shoulders.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Shrug your shoulders.</li><li>Lift them high and hold for around 5 seconds.</li><li>Then drop them into the relaxed position so they hang naturally.</li><li>Try two dropped positions – drop and then drop again even further.</li><li>Arms should be floppy and loose and shoulders should hang naturally in their groove.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Shoulder Drop Release, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Shoulder Drop Release and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'cb01d557-c84a-44c9-be03-abe479ee2fb7';

-- [Physical Starters] Shoulder Circles
UPDATE activities
SET activity = 'Shoulder Circles',
    time = 3,
    description = '<p>Start the session with Shoulder Circles to wake the body. Draw one shoulder at a time up to your ears as far as you can.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Draw one shoulder at a time up to your ears as far as you can.</li><li>Then draw an imaginary circle with your shoulders.</li><li>Right first, then left.</li><li>Then both together.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Shoulder Circles, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>After Shoulder Circles, shake out once, then find ‘singer’s feet’ before the first note.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Add an opposite pattern or faster swap on a shared cue.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'b3c2e1ae-8d15-4ce6-9d0b-516b2b483222';

-- [Physical Starters] Emotional Walking
UPDATE activities
SET activity = 'Emotional Walking',
    time = 3,
    description = '<p>Start the session with Emotional Walking to wake the body. Play the game ‘Emotional Walking’.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Play the game ‘Emotional Walking’.</li><li>Ask everyone to walk around the room, moving in and out of each other.</li><li>(Make sure they don’t just walk in a circle in the same direction; but find their own path).</li><li>Call out an emotion and ask everyone to use their body and their manner of walking to show that emotion.</li><li>Start with ‘happy’ and then move on to ‘sad’, ‘confident’, ‘angry’, ‘scared’.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Emotional Walking, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Emotional Walking and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'cc108163-830b-479c-afb5-f9e2c788b48c';

-- [Physical Starters] Emotional Walking 1-10
UPDATE activities
SET activity = 'Emotional Walking 1-10',
    time = 3,
    description = '<p>Start the session with Emotional Walking 1-10 to wake the body. Revise the ‘Emotional Walking’ game but this time vary the intensity of the emotions by using a 1 – 10 scale.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Revise the ‘Emotional Walking’ game but this time vary the intensity of the emotions by using a 1 – 10 scale. 1 being just a small indication of the emotion, 10 being the whole body and movement taken over by the emotion.</li><li>Call out ‘happy 10’ and then ‘happy 4’ for example.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Emotional Walking 1-10; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>During Emotional Walking 1-10, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Emotional Walking 1-10 in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '07c02ca7-fbb8-4e26-bbde-6dcebe9744c4';

-- [Physical Starters] Expression Morph
UPDATE activities
SET activity = 'Expression Morph',
    time = 3,
    description = '<p>Start the session with Expression Morph to wake the body. Miming with your hands, screw your face up like a piece of paper, then pull it out as flat as you can.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Miming with your hands, screw your face up like a piece of paper, then pull it out as flat as you can.</li><li>Over a count of 10, morph from one expression to another.</li><li>Start with sad and, over 10, gradually transform to radiantly happy.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Expression Morph, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Expression Morph and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '1c7fb514-e00a-4f15-9341-274233a3eecc';

-- [Physical Starters] Shake Water Nerves and Ants
UPDATE activities
SET activity = 'Shake Water Nerves and Ants',
    time = 3,
    description = '<p>Start the session with Shake Water Nerves and Ants to wake the body. Plunge their hands into an imaginary bowl of water.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Plunge their hands into an imaginary bowl of water.</li><li>Now shake your hands vigorously to get rid of all the water.</li><li>You have a sudden attack of nerves, and your knees shake uncontrollably.</li><li>Now you realise you must have ants in your pants, and you shake your bottom wildly to stop them tickling.</li><li>Can you do all three together?</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Shake Water Nerves and Ants taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>Alternate sound effects in Shake Water Nerves and Ants with a recovery breath so the class doesn’t get dizzy.</li><li>End Shake Water Nerves and Ants in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '8179bf10-841c-41b1-8727-d3278b596900';

-- [Physical Starters] Side Stretch Hold
UPDATE activities
SET activity = 'Side Stretch Hold',
    time = 3,
    description = '<p>Start the session with Side Stretch Hold to wake the body. Hold the thumb and put arms over their head and then bend to the left then the right, stretching.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Checks alignment so the voice isn’t blocked</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Hold the thumb and put arms over their head and then bend to the left then the right, stretching.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Side Stretch Hold, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Side Stretch Hold and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'f80aab5d-d1e3-42fa-a4d2-f618c71e3b46';

-- [Physical Starters] Funky Chicken
UPDATE activities
SET activity = 'Funky Chicken',
    time = 3,
    description = '<p>Start the session with Funky Chicken to wake the body. Carry out the warm-up ‘Funky Chicken’.</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Raises energy and group focus quickly</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Carry out the warm-up ‘Funky Chicken’.</li><li>Shake the left foot 8 times, then the right foot, left arm and right arm and then ‘hoolahoop’ your body 8 times.</li><li>Do the same 4 times, twice and finally once.</li><li>At the end flap your wings and shout ‘funky chicken!’.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep Funky Chicken taps light and musical — if energy spikes, freeze on a silent three then restart softer.</li><li>During Funky Chicken, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>Freeze the last shape of Funky Chicken and check ears-over-shoulders as a class.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = 'dd186732-b5a4-4a2f-b0d8-c295e025dcbf';

-- [Physical Starters] Prompt Response Actions
UPDATE activities
SET activity = 'Prompt Response Actions',
    time = 3,
    description = '<p>Start the session with Prompt Response Actions to wake the body. Say the following phrases with the class responding appropriately: pencil (hand facing up by mouth) and say ‘Aah’; ‘toast’ – flat hand by mouth;….</p><p><strong>Why it works</strong></p><ul><li>Releases tension before singing</li><li>Aligns posture for freer breath and tone</li><li>Gets the whole class moving as one ensemble</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Open floor space with room to stretch and turn. Whole class. No props needed. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Say the following phrases with the class responding appropriately: pencil (hand facing up by mouth) and say ‘Aah’.</li><li>‘toast’ – flat hand by mouth.</li><li>‘spaghetti’ – sip in with one finger pointing to their mouth.</li><li>‘water melon’ (widest mouth possible as if trying to eat a water melon).</li><li>‘Someone’s ringing the door’ (surprise face).</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Prompt Response Actions, use one short posture cue only (‘soft knees’ or ‘long spine’) so movement stays musical.</li><li>End Prompt Response Actions in a tall still shape for three counts so energy settles into posture.</li></ul><p><strong>Make it easier</strong></p><p>Do the movement without chant/song first, then add the voice.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Freeze in the final aligned posture and take one supported breath together.</p>',
    updated_at = NOW()
WHERE id = '61b53382-e0a5-4b15-b30e-a04344ebae88';

