-- [Breathing Exercises] Full Exhale and Refill
UPDATE activities
SET activity = 'Full Exhale and Refill',
    time = 2,
    description = '<p>Use Full Exhale and Refill to settle breath and posture before singing. Blow out all the breath in the body – without the body collapsing – then let the body breathe in deeply, quickly and naturally without shoulders….</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Practises controlled release of air without strain</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Blow out all the breath in the body – without the body collapsing – then let the body breathe in deeply, quickly and naturally without shoulders lifting.</li><li>Bend forward with hands out in front and do the same thing, feeling the breath go into the back on the inhalation.</li><li>Now repeat, standing up straight.</li><li>Really notice the breath filling the whole of the middle part of the body, front and back (this is where the support for the voice comes from.).</li></ol><p><strong>Teacher tips</strong></p><ul><li>In Full Exhale and Refill, pause after the first full cycle and ask one pupil what they felt move — name that sensation.</li><li>After Full Exhale and Refill, ask ‘where did the air go?’ and point to ribs/tummy before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = '29a50dc6-4a6e-4200-a48d-5f7200c3b7a7';

-- [Breathing Exercises] Rag Doll Sshh
UPDATE activities
SET activity = 'Rag Doll Sshh',
    time = 2,
    description = '<p>Use Rag Doll Sshh to settle breath and posture before singing. Bend over bending the knees and hang like a rag doll.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Practises controlled release of air without strain</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Bend over bending the knees and hang like a rag doll.</li><li>Note how you are breathing.</li><li>Slowly come up.</li><li>Add a sshh sound as you go over – don’t inhale until you are empty – pause before inhaling.</li><li>Inhale as you come up.</li></ol><p><strong>Teacher tips</strong></p><ul><li>In Rag Doll Sshh, pause after the first full cycle and ask one pupil what they felt move — name that sensation.</li><li>After Rag Doll Sshh, ask ‘where did the air go?’ and point to ribs/tummy before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = 'b9594764-22de-4c1b-a8de-03d20ac7438e';

-- [Breathing Exercises] Fill the Glass Breath
UPDATE activities
SET activity = 'Fill the Glass Breath',
    time = 2,
    description = '<p>Use Fill the Glass Breath to settle breath and posture before singing. Stress how important it is to breathe filling their lungs right from the bottom to the top with air and not to just use shallow top up breaths.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Calms the class and focuses listening before repertoire</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Stress how important it is to breathe filling their lungs right from the bottom to the top with air and not to just use shallow top up breaths.</li><li>Imagine taking in the breath through their belly button.</li><li>Imagine they are filling a glass of water up from the bottom of the glass.</li></ol><p><strong>Teacher tips</strong></p><ul><li>In Fill the Glass Breath, cue ‘fill from the bottom’ and watch shoulders: if they lift, mime pushing the ring/balloon lower.</li><li>During Fill the Glass Breath, hands on ribs/tummy stay light — expansion should be sideways/forwards, not a heaved chest.</li><li>After Fill the Glass Breath, ask ‘where did the air go?’ and point to ribs/tummy before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = '53a97983-92a1-46e7-8976-52baf5c78660';

-- [Breathing Exercises] Bad Posture Breathing Demo
UPDATE activities
SET activity = 'Bad Posture Breathing Demo',
    time = 2,
    description = '<p>Use Bad Posture Breathing Demo to settle breath and posture before singing. Practice bad postures to see how difficult it is to breathe properly eg.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Links posture and breathing muscles for clearer tone</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Practice bad postures to see how difficult it is to breathe properly eg. 1) Lock knees and stick their bottoms out.</li><li>2) Slump their body.</li><li>3) Stand stiff as a soldier.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Model the Bad Posture Breathing Demo posture check once, then let pairs self-check: ears over shoulders, soft knees.</li><li>In Bad Posture Breathing Demo, pause after the first full cycle and ask one pupil what they felt move — name that sensation.</li><li>Leave Bad Posture Breathing Demo on a silent shared inhale — then speak the first lyric on that same breath feeling.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Add a longer counted exhale or link straight into the first phrase of a song.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = '1cff6c57-5115-4202-9d3c-d6d04606cac9';

-- [Breathing Exercises] Surprised Breath In
UPDATE activities
SET activity = 'Surprised Breath In',
    time = 2,
    description = '<p>Use Surprised Breath In to settle breath and posture before singing. Clap your hands to signal everyone to look surprised and, with an open throat, allow the breath to come in easily.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Calms the class and focuses listening before repertoire</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Clap your hands to signal everyone to look surprised and, with an open throat, allow the breath to come in easily.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>In Surprised Breath In, pause after the first full cycle and ask one pupil what they felt move — name that sensation.</li><li>Leave Surprised Breath In on a silent shared inhale — then speak the first lyric on that same breath feeling.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Add a longer counted exhale or link straight into the first phrase of a song.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = '1a53c954-b637-4004-bbec-8d90a33d2683';

-- [Breathing Exercises] Drips and Hiss
UPDATE activities
SET activity = 'Drips and Hiss',
    time = 2,
    description = '<p>Use Drips and Hiss to settle breath and posture before singing. Imagine drips trickling down your back.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Calms the class and focuses listening before repertoire</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Imagine drips trickling down your back.</li><li>Breathe in over the count of 4 then hiss for 4.</li><li>Repeat, each time extending the hiss.</li><li>How far can they get to?</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep the airflow in Drips and Hiss quiet and even; stop if throats tighten and rematch on a softer ‘sss’.</li><li>In Drips and Hiss, pause after the first full cycle and ask one pupil what they felt move — name that sensation.</li><li>Repeat Drips and Hiss once seated if standing posture collapsed — compare the two sensations.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = '720ef255-4f3f-4ceb-89a3-921f6f3f9ae1';

-- [Breathing Exercises] Belly Laugh Breath
UPDATE activities
SET activity = 'Belly Laugh Breath',
    time = 2,
    description = '<p>Use Belly Laugh Breath to settle breath and posture before singing. Now turn the out-breath into some confident belly laughs: ‘Ha ha!.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Links posture and breathing muscles for clearer tone</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Now turn the out-breath into some confident belly laughs: ‘Ha ha!</li><li>Ho ho!</li><li>Ha ha ha!’ and feel the sound being propelled from your tummy.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Belly Laugh Breath, hands on ribs/tummy stay light — expansion should be sideways/forwards, not a heaved chest.</li><li>Keep theatrical laughs in Belly Laugh Breath supported from the middle — fun, not scraped from the throat.</li><li>After Belly Laugh Breath, ask ‘where did the air go?’ and point to ribs/tummy before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = '0334146e-96bc-46f0-a34b-d1a14ef63cf9';

-- [Breathing Exercises] Annoyed Ssh and Zzssh
UPDATE activities
SET activity = 'Annoyed Ssh and Zzssh',
    time = 2,
    description = '<p>Use Annoyed Ssh and Zzssh to settle breath and posture before singing. Imagine someone is really annoying you and you go ‘Ssh’ – feel the tummy move.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Practises controlled release of air without strain</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Imagine someone is really annoying you and you go ‘Ssh’ – feel the tummy move.</li><li>Do 3 in succession at a reasonable tempo.</li><li>Now make them gentler, but still coming from the tummy.</li><li>Next use a voiced tone ‘Zzssh’ sliding up and down in pitch.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Annoyed Ssh and Zzssh, hands on ribs/tummy stay light — expansion should be sideways/forwards, not a heaved chest.</li><li>Keep the airflow in Annoyed Ssh and Zzssh quiet and even; stop if throats tighten and rematch on a softer ‘sss’.</li><li>After Annoyed Ssh and Zzssh, ask ‘where did the air go?’ and point to ribs/tummy before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = '9fedb71e-3992-41f7-afe6-1a25121c06bd';

-- [Breathing Exercises] Stage Laugh Rib Support
UPDATE activities
SET activity = 'Stage Laugh Rib Support',
    time = 2,
    description = '<p>Use Stage Laugh Rib Support to settle breath and posture before singing. Explain that all singing requires breath support and when singing higher notes this diaphragm support is particularly important.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Links posture and breathing muscles for clearer tone</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Explain that all singing requires breath support and when singing higher notes this diaphragm support is particularly important.</li><li>Place the hands on the lower part of the rib cage, with some of the hand below the bottom rib.</li><li>Then do a stage laugh – Father Christmas is a good example to mimic.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Stage Laugh Rib Support, hands on ribs/tummy stay light — expansion should be sideways/forwards, not a heaved chest.</li><li>Keep theatrical laughs in Stage Laugh Rib Support supported from the middle — fun, not scraped from the throat.</li><li>After Stage Laugh Rib Support, ask ‘where did the air go?’ and point to ribs/tummy before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = '8bceeacd-fdaf-45f8-8592-2ed10c7b21a4';

-- [Breathing Exercises] Silent Laugh Open Throat
UPDATE activities
SET activity = 'Silent Laugh Open Throat',
    time = 2,
    description = '<p>Use Silent Laugh Open Throat to settle breath and posture before singing. Revise the importance of a nice open throat when singing.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Calms the class and focuses listening before repertoire</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Revise the importance of a nice open throat when singing.</li><li>You can get the same feeling by laughing silently.</li><li>Imagine that you are sitting at the back of the classroom, and your friend has made you laugh but you do not want the teacher to hear.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep theatrical laughs in Silent Laugh Open Throat supported from the middle — fun, not scraped from the throat.</li><li>In Silent Laugh Open Throat, pause after the first full cycle and ask one pupil what they felt move — name that sensation.</li><li>Leave Silent Laugh Open Throat on a silent shared inhale — then speak the first lyric on that same breath feeling.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = '9b32c075-9b89-42c3-a4af-fd122b091ed4';

-- [Breathing Exercises] Open Book Jaw
UPDATE activities
SET activity = 'Open Book Jaw',
    time = 2,
    description = '<p>Use Open Book Jaw to settle breath and posture before singing. Run fingers down their jaw imagining they are opening up a book – aim for a nice wide open jaw.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Calms the class and focuses listening before repertoire</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Run fingers down their jaw imagining they are opening up a book – aim for a nice wide open jaw.</li><li>Tap all the bones in their face.</li><li>The idea is to create a big open space inside the mouth – their cathedral, rather than necessarily opening their jaw wider.</li></ol><p><strong>Teacher tips</strong></p><ul><li>In Open Book Jaw, pause after the first full cycle and ask one pupil what they felt move — name that sensation.</li><li>Repeat Open Book Jaw once seated if standing posture collapsed — compare the two sensations.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = 'dea16005-1710-4239-8fb8-5e5b47aae318';

-- [Breathing Exercises] Panting Dogs Monkeys Rockets
UPDATE activities
SET activity = 'Panting Dogs Monkeys Rockets',
    time = 2,
    description = '<p>Use Panting Dogs Monkeys Rockets to settle breath and posture before singing. Make the sound of panting dogs, monkeys, rockets.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Calms the class and focuses listening before repertoire</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Make the sound of panting dogs, monkeys, rockets.</li><li>Massage the cheek muscles.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Alternate sound effects in Panting Dogs Monkeys Rockets with a recovery breath so the class doesn’t get dizzy.</li><li>In Panting Dogs Monkeys Rockets, pause after the first full cycle and ask one pupil what they felt move — name that sensation.</li><li>Repeat Panting Dogs Monkeys Rockets once seated if standing posture collapsed — compare the two sensations.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = '8044972a-6d64-42f4-8257-30a24c904027';

-- [Breathing Exercises] Candle Volume Control
UPDATE activities
SET activity = 'Candle Volume Control',
    time = 2,
    description = '<p>Use Candle Volume Control to settle breath and posture before singing. Think about dynamic contrast needed in the song to match the mood of the lyrics and music.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Practises controlled release of air without strain</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Think about dynamic contrast needed in the song to match the mood of the lyrics and music.</li><li>How loudly or softly you sing depends on the amount and speed of the airflow used to make the sounds.</li><li>Imagine singing with a lighted candle in front of their mouth.</li><li>Sing a soft ‘ooh’ sound without blowing out your candle.</li><li>Now sing a louder ‘Ooh’, this time blowing out your imaginary candle.</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Candle Volume Control, keep the imaginary flame small — if air blasts, reset to a gentle stream on one finger.</li><li>In Candle Volume Control, pause after the first full cycle and ask one pupil what they felt move — name that sensation.</li><li>Leave Candle Volume Control on a silent shared inhale — then speak the first lyric on that same breath feeling.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = '97203a1c-b94c-462c-9ee4-11b3940b0e9b';

-- [Breathing Exercises] Breath Ladder Numbers
UPDATE activities
SET activity = 'Breath Ladder Numbers',
    time = 2,
    description = '<p>Use Breath Ladder Numbers to settle breath and posture before singing. Sing the following on a monotone: 4321 321 21.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Calms the class and focuses listening before repertoire</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sing the following on a monotone: 4321 321 21.</li><li>Move up a semitone and increase the number sequence by one: 54321 4321 321 21.</li><li>Continue until they run out of breath.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Breath Ladder Numbers; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>In Breath Ladder Numbers, pause after the first full cycle and ask one pupil what they felt move — name that sensation.</li><li>Repeat Breath Ladder Numbers once seated if standing posture collapsed — compare the two sensations.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = '1a7011c1-4a4c-4008-b9b3-153c4de16884';

-- [Breathing Exercises] Hot-Air Balloon Breath
UPDATE activities
SET activity = 'Hot-Air Balloon Breath',
    time = 2,
    description = '<p>Use Hot-Air Balloon Breath to settle breath and posture before singing. Imagine the tummy is a big hot-air balloon and they are filling the tank from the bottom.</p><p><strong>Why it works</strong></p><ul><li>Builds awareness of supported, low breath</li><li>Prepares steady airflow for singing phrases</li><li>Practises controlled release of air without strain</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Stand or sit tall with free shoulders. Whole class. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Imagine the tummy is a big hot-air balloon and they are filling the tank from the bottom.</li><li>Gently blow out air as far as they can.</li><li>When they feel they cannot get rid of any more air relax the tummy and notice how you automatically take air in through your nose.</li><li>Repeat but open your mouth.</li></ol><p><strong>Teacher tips</strong></p><ul><li>In Hot-Air Balloon Breath, cue ‘fill from the bottom’ and watch shoulders: if they lift, mime pushing the ring/balloon lower.</li><li>During Hot-Air Balloon Breath, hands on ribs/tummy stay light — expansion should be sideways/forwards, not a heaved chest.</li><li>Leave Hot-Air Balloon Breath on a silent shared inhale — then speak the first lyric on that same breath feeling.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models one slow cycle; class joins on the out-breath only.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Transfer the same breath feeling into the opening line of today’s repertoire.</p>',
    updated_at = NOW()
WHERE id = '42920e5e-da0c-4173-9c0d-d401102dee0b';

-- [Facial Warm-Ups / Diction] Lip Roll Horse
UPDATE activities
SET activity = 'Lip Roll Horse',
    time = 2,
    description = '<p>Warm the face and diction with Lip Roll Horse. Make your lips very loose and floppy and do a lip-roll to a ‘p’ sound, like a horse.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Loosens lips for freer onset and buzz</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Make your lips very loose and floppy and do a lip-roll to a ‘p’ sound, like a horse.</li><li>Repeat to a rolled ‘r’.</li></ol><p><strong>Teacher tips</strong></p><ul><li>If the lip buzz in Lip Roll Horse won’t start, add a tiny voiced ‘b’ or ‘v’ underneath — never force dry lips.</li><li>For Lip Roll Horse, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>After Lip Roll Horse, spot one consonant that still smudges and drill only that word.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Raise the tempo or move the pattern up by semitones while keeping every consonant.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = 'a48d6d06-2564-4527-9845-80ba9d3e99e0';

-- [Facial Warm-Ups / Diction] Chew Toffee Face Loosen
UPDATE activities
SET activity = 'Chew Toffee Face Loosen',
    time = 2,
    description = '<p>Warm the face and diction with Chew Toffee Face Loosen. Loosen the face by imagining they are chewing a great big toffee.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Makes warm-up playful so diction feels low-stakes</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Loosen the face by imagining they are chewing a great big toffee.</li><li>Squeeze the eyes together as if squinting from the sun then blow the cheeks out.</li><li>Then chew a bit more and repeat.</li></ol><p><strong>Teacher tips</strong></p><ul><li>In Chew Toffee Face Loosen, keep the chew huge and silent for two beats before adding voice — floppy face, not clenched jaw.</li><li>For Chew Toffee Face Loosen, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>Land Chew Toffee Face Loosen on a whispered clear sentence, then the same sentence sung.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = '65510160-3feb-4e53-83d7-7f5c59449143';

-- [Facial Warm-Ups / Diction] Diction Sentence
UPDATE activities
SET activity = 'Diction Sentence',
    time = 2,
    description = '<p>Warm the face and diction with Diction Sentence. Say the words ‘Diction is done with the tip of the tongue and the teeth.’.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Strengthens tongue agility for consonants</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Say the words ‘Diction is done with the tip of the tongue and the teeth.’.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Diction Sentence, exaggerate tip-of-tongue consonants slowly first; only speed up when every syllable stays clear.</li><li>For Diction Sentence, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>After Diction Sentence, spot one consonant that still smudges and drill only that word.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = '4e540771-8cb9-4c05-a428-e5c81ae2bcb4';

-- [Facial Warm-Ups / Diction] Shabba Doo Chant
UPDATE activities
SET activity = 'Shabba Doo Chant',
    time = 2,
    description = '<p>Warm the face and diction with Shabba Doo Chant. Chant the scat words – ‘Shabba doo dabba doo, dibba doo dabba doo, dibba doo dabba doo, dibba doo day’.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Makes warm-up playful so diction feels low-stakes</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Chant the scat words – ‘Shabba doo dabba doo, dibba doo dabba doo, dibba doo dabba doo, dibba doo day’.</li><li>Learn a phrase at a time then put two phrases together with a count of 4 after both before repeating them.</li><li>Then practise the last two phrases separately before putting the whole chant together.</li><li>Then sing it on 2 notes a 5th apart starting with the higher note.</li><li>Move onto the other note after the 1st syllable of the next phrase.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Teach one Shabba Doo Chant phrase call-and-response before chaining; clap a pulse underneath so timing stays shared.</li><li>For Shabba Doo Chant, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>Land Shabba Doo Chant on a whispered clear sentence, then the same sentence sung.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = '44f79a68-77c3-4490-823a-4fb8efa89fd9';

-- [Facial Warm-Ups / Diction] Mama Made Me Mash M'n'M's
