-- [Facial Warm-Ups / Diction] Se Ke Pe Te March
UPDATE activities
SET activity = 'Se Ke Pe Te March',
    time = 2,
    description = '<p>Warm the face and diction with Se Ke Pe Te March. March on the spot saying each of the following sounds in time to the beat – ‘Se, ke, pe, te’.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Makes warm-up playful so diction feels low-stakes</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>March on the spot saying each of the following sounds in time to the beat – ‘Se, ke, pe, te’.</li><li>Keep the feet marking the same beat but now say each sound twice – double time.</li><li>Increase this to triple time and finally quadruple time.</li><li>Switch from one to the other.</li><li>Gradually speed the beat up.</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Se Ke Pe Te March, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>After Se Ke Pe Te March, spot one consonant that still smudges and drill only that word.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = '760ee979-1df1-4125-bd4a-ab5bfa3ac41c';

-- [Facial Warm-Ups / Diction] Red Lorry Yellow Lorry
