-- [Facial Warm-Ups / Diction] Haribo Chew
UPDATE activities
SET activity = 'Haribo Chew',
    time = 2,
    description = '<p>Warm the face and diction with Haribo Chew. Put their hand out in front of them and place on it 4 packets of Haribo sweets.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Makes warm-up playful so diction feels low-stakes</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Put their hand out in front of them and place on it 4 packets of Haribo sweets.</li><li>Put a bag into their mouth and chew.</li><li>Chew as fast as they can then swallow.</li><li>Then repeat.</li></ol><p><strong>Teacher tips</strong></p><ul><li>In Haribo Chew, keep the chew huge and silent for two beats before adding voice — floppy face, not clenched jaw.</li><li>For Haribo Chew, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>Land Haribo Chew on a whispered clear sentence, then the same sentence sung.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Raise the tempo or move the pattern up by semitones while keeping every consonant.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = 'c5cbb6e4-06f8-4254-be05-e15cd91adeda';

-- [Facial Warm-Ups / Diction] Yaya Mama Mm Tongue
UPDATE activities
SET activity = 'Yaya Mama Mm Tongue',
    time = 2,
    description = '<p>Warm the face and diction with Yaya Mama Mm Tongue. Say ‘yayayayayaya’ and ‘mamamamama’, ensuring the jaw is loose.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Strengthens tongue agility for consonants</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Say ‘yayayayayaya’ and ‘mamamamama’, ensuring the jaw is loose.</li><li>Next make a hummed ‘mm’, keeping lips relaxed so they buzz.</li><li>Stick out your tongue and lick all around your teeth, top and bottom.</li></ol><p><strong>Teacher tips</strong></p><ul><li>If the lip buzz in Yaya Mama Mm Tongue won’t start, add a tiny voiced ‘b’ or ‘v’ underneath — never force dry lips.</li><li>For Yaya Mama Mm Tongue, exaggerate tip-of-tongue consonants slowly first; only speed up when every syllable stays clear.</li><li>Aim for a continuous buzz in Yaya Mama Mm Tongue with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = 'c84b7181-b877-4aa2-808f-6652be1aa1e9';

