-- [Facial Warm-Ups / Diction] Lip Brrr Tractor
UPDATE activities
SET activity = 'Lip Brrr Tractor',
    time = 2,
    description = '<p>Warm the face and diction with Lip Brrr Tractor. Make a ‘Brrr’ sound with their lips and then raise the pitch.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Loosens lips for freer onset and buzz</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Make a ‘Brrr’ sound with their lips and then raise the pitch.</li><li>Make the sound low down like they are driving a tractor and getting faster.</li></ol><p><strong>Teacher tips</strong></p><ul><li>If the lip buzz in Lip Brrr Tractor won’t start, add a tiny voiced ‘b’ or ‘v’ underneath — never force dry lips.</li><li>For Lip Brrr Tractor, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>Land Lip Brrr Tractor on a whispered clear sentence, then the same sentence sung.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = '618875c1-b3bf-4944-8edc-30647a697611';

-- [Facial Warm-Ups / Diction] Silent Yawn Ah
UPDATE activities
SET activity = 'Silent Yawn Ah',
    time = 2,
    description = '<p>Warm the face and diction with Silent Yawn Ah. Make a big, silent yawn, and feel the space created at the back of the throat.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Strengthens tongue agility for consonants</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Make a big, silent yawn, and feel the space created at the back of the throat.</li><li>Say ‘ah’ through a yawn, sliding from high to low and dropping the tongue slightly at the back.</li><li>Imagine the space inside their mouth is huge, like a cave or a large hall.</li><li>Now sing ‘ah’ on any note.</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Silent Yawn Ah, exaggerate tip-of-tongue consonants slowly first; only speed up when every syllable stays clear.</li><li>For Silent Yawn Ah, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>Close Silent Yawn Ah by mouthing the pattern silently, then add voice — clarity first.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = 'cd832d40-1429-44de-bf66-d131f1886614';

