-- [Facial Warm-Ups / Diction] Bubblegum Tongue Chew
UPDATE activities
SET activity = 'Bubblegum Tongue Chew',
    time = 2,
    description = '<p>Warm the face and diction with Bubblegum Tongue Chew. To exercise the tongue imagine they are chewing a very big piece of pink bubblegum with an open mouth, loudly and quickly – feel the lips, tongue….</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Strengthens tongue agility for consonants</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>To exercise the tongue imagine they are chewing a very big piece of pink bubblegum with an open mouth, loudly and quickly – feel the lips, tongue and jaw wake up.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>If the lip buzz in Bubblegum Tongue Chew won’t start, add a tiny voiced ‘b’ or ‘v’ underneath — never force dry lips.</li><li>For Bubblegum Tongue Chew, exaggerate tip-of-tongue consonants slowly first; only speed up when every syllable stays clear.</li><li>In Bubblegum Tongue Chew, keep the chew huge and silent for two beats before adding voice — floppy face, not clenched jaw.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = 'b98aa396-85bf-405b-b3f4-cad3beb263c9';

-- [Facial Warm-Ups / Diction] Ice-Cream Tongue Licks
UPDATE activities
SET activity = 'Ice-Cream Tongue Licks',
    time = 2,
    description = '<p>Warm the face and diction with Ice-Cream Tongue Licks. Imagine they have just eaten an ice-cream with 100’s and 1000’s all over it which they now have all around their mouth!.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Strengthens tongue agility for consonants</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Imagine they have just eaten an ice-cream with 100’s and 1000’s all over it which they now have all around their mouth!</li><li>Lick them off one at a time, going from corner to corner.</li><li>Try to keep the jaw still to work the tongue.</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Ice-Cream Tongue Licks, exaggerate tip-of-tongue consonants slowly first; only speed up when every syllable stays clear.</li><li>For Ice-Cream Tongue Licks, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>Land Ice-Cream Tongue Licks on a whispered clear sentence, then the same sentence sung.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = 'ee7a2629-02c8-4ec5-a239-4fb66ef1aef0';

-- [Facial Warm-Ups / Diction] Big Yawn Stretch
UPDATE activities
SET activity = 'Big Yawn Stretch',
    time = 2,
    description = '<p>Warm the face and diction with Big Yawn Stretch. Yawn out loud first in an exaggerated manner, use hands to stretch out – feel the space inside your mouth.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Makes warm-up playful so diction feels low-stakes</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Yawn out loud first in an exaggerated manner, use hands to stretch out – feel the space inside your mouth.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Big Yawn Stretch, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>After Big Yawn Stretch, spot one consonant that still smudges and drill only that word.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Raise the tempo or move the pattern up by semitones while keeping every consonant.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = '7ea5e338-5a6e-40bb-afd2-e6e9c1838203';

-- [Facial Warm-Ups / Diction] Dry vs Lively Delivery
UPDATE activities
SET activity = 'Dry vs Lively Delivery',
    time = 2,
    description = '<p>Warm the face and diction with Dry vs Lively Delivery. Speak the following sentence in a dry, monotone voice and then immediately contrast it with a lively, normal delivery.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Makes warm-up playful so diction feels low-stakes</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Speak the following sentence in a dry, monotone voice and then immediately contrast it with a lively, normal delivery. “I went to the Beyonce concert on Saturday and it was the most fantastic night of my life.” Or, “In the last minute of the game Wayne Rooney shot through the centre, dodged two defenders, and scored.</li><li>It was unbelievable!” Discuss which are the important words and how the speaker would be feeling.</li><li>How does the listener know they’re feeling that?</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Dry vs Lively Delivery, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>Land Dry vs Lively Delivery on a whispered clear sentence, then the same sentence sung.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = 'bda80137-8b6f-4da9-93ae-06d61143056f';

-- [Facial Warm-Ups / Diction] Ka Ha Ssh Conductor Sounds
UPDATE activities
SET activity = 'Ka Ha Ssh Conductor Sounds',
    time = 2,
    description = '<p>Warm the face and diction with Ka Ha Ssh Conductor Sounds. Start with ‘Ka’ on beat one of a 4 beat pattern.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Makes warm-up playful so diction feels low-stakes</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Start with ‘Ka’ on beat one of a 4 beat pattern.</li><li>Then follow this with any high note of their choice to the syllable ‘Ha’ and hold on for 4 beats.</li><li>Switch from the ‘Ka’ to ‘Ha’ every 4 beats.</li><li>Then sing a random selection of ‘Ka’s’ changing pitch with each one and using any rhythm of their choice.</li><li>Then switch to a ‘Ssh’ held on for 8 beats followed by a slow glissando on the syllable ‘Ss’.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep the airflow in Ka Ha Ssh Conductor Sounds quiet and even; stop if throats tighten and rematch on a softer ‘sss’.</li><li>In Ka Ha Ssh Conductor Sounds, the leader’s hand must move smoothly — practise the gesture silently once so voices don’t jump.</li><li>Land Ka Ha Ssh Conductor Sounds on a whispered clear sentence, then the same sentence sung.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = '1dd8e744-7240-4e52-9fab-448e51d00f9a';

-- [Facial Warm-Ups / Diction] Santa Ho Ho Ho
UPDATE activities
SET activity = 'Santa Ho Ho Ho',
    time = 2,
    description = '<p>Warm the face and diction with Santa Ho Ho Ho. Imagine you are Santa Claus and imitate Santa’s jolly “Ho, ho, ho!” with your voice, first out loud and then silently.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Makes warm-up playful so diction feels low-stakes</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Imagine you are Santa Claus and imitate Santa’s jolly “Ho, ho, ho!” with your voice, first out loud and then silently.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Santa Ho Ho Ho, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>Close Santa Ho Ho Ho by mouthing the pattern silently, then add voice — clarity first.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Raise the tempo or move the pattern up by semitones while keeping every consonant.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = '90f423c1-adbb-4deb-bdb5-b90a446a3e02';

-- [Facial Warm-Ups / Diction] Alphabet Monotone
UPDATE activities
SET activity = 'Alphabet Monotone',
    time = 2,
    description = '<p>Warm the face and diction with Alphabet Monotone. Sing through the alphabet on a monotone with chords I &amp; IV alternating as an accompaniment, with the letter ‘Y’ sung a semitone below with chord V….</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Makes warm-up playful so diction feels low-stakes</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sing through the alphabet on a monotone with chords I &amp; IV alternating as an accompaniment, with the letter ‘Y’ sung a semitone below with chord V accompanying.</li><li>Raise up a semitone on each repeat.</li><li>Gradually get faster.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Alphabet Monotone; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>For Alphabet Monotone, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>Land Alphabet Monotone on a whispered clear sentence, then the same sentence sung.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = '085923c7-28f0-4fdc-ba6c-76fd30edcf4b';

-- [Facial Warm-Ups / Diction] Big Apple Ah
UPDATE activities
SET activity = 'Big Apple Ah',
    time = 2,
    description = '<p>Warm the face and diction with Big Apple Ah. Lifting of both the soft palate and facial muscles: this can be achieved by telling the pupil to imagine they are taking a bite from the world’s….</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Makes warm-up playful so diction feels low-stakes</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Lifting of both the soft palate and facial muscles: this can be achieved by telling the pupil to imagine they are taking a bite from the world’s biggest apple – then sing ‘ah’ in this position.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Big Apple Ah, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>Land Big Apple Ah on a whispered clear sentence, then the same sentence sung.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = '9a211725-932f-449b-9b8a-c4734bfee343';

-- [Facial Warm-Ups / Diction] Copy Short and Long Sounds
UPDATE activities
SET activity = 'Copy Short and Long Sounds',
    time = 2,
    description = '<p>Warm the face and diction with Copy Short and Long Sounds. Ask the group to copy you as you sing a mixture of short vocal sounds eg.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Makes warm-up playful so diction feels low-stakes</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Ask the group to copy you as you sing a mixture of short vocal sounds eg. ff k t as well as longer sounds such as pah.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Copy Short and Long Sounds, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>After Copy Short and Long Sounds, spot one consonant that still smudges and drill only that word.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = '25ccdea2-e8e9-4886-9581-2ad5d36a8b46';

-- [Facial Warm-Ups / Diction] Exaggerated Song Words
UPDATE activities
SET activity = 'Exaggerated Song Words',
    time = 2,
    description = '<p>Warm the face and diction with Exaggerated Song Words. Practise the words of the song being rehearsed, exaggerating the mouth movements: notice what the mouth-shapes feel like.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Makes warm-up playful so diction feels low-stakes</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Practise the words of the song being rehearsed, exaggerating the mouth movements: notice what the mouth-shapes feel like.</li><li>(Particular good for songs in an unfamiliar language.).</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Exaggerated Song Words, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>After Exaggerated Song Words, spot one consonant that still smudges and drill only that word.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = 'aacd8e00-d55d-461c-bf3b-46fdb1ffcadd';

-- [Facial Warm-Ups / Diction] Whisper and Mime Phrases
UPDATE activities
SET activity = 'Whisper and Mime Phrases',
    time = 2,
    description = '<p>Warm the face and diction with Whisper and Mime Phrases. Say the following words in a whisper and then mouthed with no breath.</p><p><strong>Why it works</strong></p><ul><li>Wakes facial muscles for clear diction</li><li>Improves articulation without forcing the voice</li><li>Makes warm-up playful so diction feels low-stakes</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing or seated circle so everyone can see mouths. No props needed. About 2 minutes.</p><p><strong>How to do it</strong></p><ol><li>Say the following words in a whisper and then mouthed with no breath. 1.</li><li>Another and another. 2.</li><li>Edges blur and intersect, where do all the lines connect? 3.</li><li>Birds are fish and fish are birds. 4.</li><li>Cities turning into words.</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Whisper and Mime Phrases, contrast a muddy version with a crystal-clear version so the diction target is obvious.</li><li>Land Whisper and Mime Phrases on a whispered clear sentence, then the same sentence sung.</li></ul><p><strong>Make it easier</strong></p><p>Speak the pattern slowly in unison before any pitch or speed challenge.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Drop the warm-up consonants into a tricky lyric from the song.</p>',
    updated_at = NOW()
WHERE id = '31771739-566c-47d7-8d35-9de98e171b3c';

-- [Pitch Exercises] Sing Ng Siren
UPDATE activities
SET activity = 'Sing Ng Siren',
    time = 3,
    description = '<p>Explore pitch and listening with Sing Ng Siren. Sirening is the best vocal warm-up technique.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sirening is the best vocal warm-up technique.</li><li>Say ‘Sing’ and hold the ‘ng’ sound.</li><li>Aiming for no air and not very much volume so that you’re not pushing too much.</li><li>Sing a sustained sound on one note first then travel up and down the vocal range on this sound as quietly as you can.</li><li>The sound should be entirely produced out of the nose, not the mouth, so the resonance is in the nose.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Aim for a continuous buzz in Sing Ng Siren with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>On Sing Ng Siren, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After Sing Ng Siren, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'cc493b03-d3f7-4fb4-a806-9b70c311e26b';

-- [Pitch Exercises] Laughing Ng Hand Follow
UPDATE activities
SET activity = 'Laughing Ng Hand Follow',
    time = 3,
    description = '<p>Explore pitch and listening with Laughing Ng Hand Follow. Say the word ‘laughing’ and then hold on to the ‘ng’ whilst following the conductors hand direction moving up and down.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Say the word ‘laughing’ and then hold on to the ‘ng’ whilst following the conductors hand direction moving up and down.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Aim for a continuous buzz in Laughing Ng Hand Follow with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>In Laughing Ng Hand Follow, the leader’s hand must move smoothly — practise the gesture silently once so voices don’t jump.</li><li>Keep theatrical laughs in Laughing Ng Hand Follow supported from the middle — fun, not scraped from the throat.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'ad83d334-cdcf-4b70-ac2f-3eb36fc1787b';

-- [Pitch Exercises] Draw an Animal on Ng
UPDATE activities
SET activity = 'Draw an Animal on Ng',
    time = 3,
    description = '<p>Explore pitch and listening with Draw an Animal on Ng. Think of an animal to draw in the air.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Think of an animal to draw in the air.</li><li>Sing the word ‘sing’, holding onto the ‘ng’ whilst drawing this animal.</li><li>Pitch to rise and fall with their pencil.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Aim for a continuous buzz in Draw an Animal on Ng with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>Keep drawn shapes in Draw an Animal on Ng large and slow so pitch can travel; switch animals only when the buzz stays connected.</li><li>After Draw an Animal on Ng, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'da7c6038-be6e-4c5d-ad78-4f659b4ef824';

-- [Pitch Exercises] Mm to Ng to Ah
UPDATE activities
SET activity = 'Mm to Ng to Ah',
    time = 3,
    description = '<p>Explore pitch and listening with Mm to Ng to Ah. Begin by humming ‘mm’ on any pitch.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Begin by humming ‘mm’ on any pitch.</li><li>Drop the jaw slightly and ensure lips are relaxed and floppy, so the whole head ‘rings’.</li><li>Next say the word ‘sing’ and hold the ‘ng’ sound with the mouth slightly open.</li><li>The feeling is like a laser beam coming out of the top of the head.</li><li>Breathing should be relaxed and the sound full but not forced.</li></ol><p><strong>Teacher tips</strong></p><ul><li>If the lip buzz in Mm to Ng to Ah won’t start, add a tiny voiced ‘b’ or ‘v’ underneath — never force dry lips.</li><li>Aim for a continuous buzz in Mm to Ng to Ah with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>Finish Mm to Ng to Ah descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '8b697872-a737-4743-8290-46cefba2a8b8';

-- [Pitch Exercises] Whoah Voice Juggling
UPDATE activities
SET activity = 'Whoah Voice Juggling',
    time = 3,
    description = '<p>Explore pitch and listening with Whoah Voice Juggling. Juggling with your voice (like sirening) but to a ‘Whoah’ sound.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Juggling with your voice (like sirening) but to a ‘Whoah’ sound.</li><li>Follow the conductors hand for the pitch direction.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Aim for a continuous buzz in Whoah Voice Juggling with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>In Whoah Voice Juggling, the leader’s hand must move smoothly — practise the gesture silently once so voices don’t jump.</li><li>Finish Whoah Voice Juggling descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '4907eaac-2ca8-4d1e-8d7f-0e9e00c658a6';

-- [Pitch Exercises] Ball Siren Ooo
UPDATE activities
SET activity = 'Ball Siren Ooo',
    time = 3,
    description = '<p>Explore pitch and listening with Ball Siren Ooo. Have a large ball and ask two children to bounce/roll/throw it from one to the other.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Have a large ball and ask two children to bounce/roll/throw it from one to the other.</li><li>The rest of the group to siren the pitch to ‘Ooo’.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Aim for a continuous buzz in Ball Siren Ooo with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>On Ball Siren Ooo, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Resolve Ball Siren Ooo onto a comfortable mid-range hum before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'a52c173d-9522-4fc4-be48-0676b48c65e4';

-- [Pitch Exercises] Fumble Fee / Kumble Kee
UPDATE activities
SET activity = 'Fumble Fee / Kumble Kee',
    time = 3,
    description = '<p>Explore pitch and listening with Fumble Fee / Kumble Kee. Sing the phrase ‘Fumble fee fumble fee fumble fum’ to a descending pattern.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sing the phrase ‘Fumble fee fumble fee fumble fum’ to a descending pattern.</li><li>Repeat a semitone higher to the words ‘Kumble kee’, then ‘Tumble tee’ and ‘Bumble Bee’.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Fumble Fee / Kumble Kee; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On Fumble Fee / Kumble Kee, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Resolve Fumble Fee / Kumble Kee onto a comfortable mid-range hum before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'c0935cb4-9c6d-4a07-b2bf-6d468673424d';

-- [Pitch Exercises] Vowel Phrase Families
UPDATE activities
SET activity = 'Vowel Phrase Families',
    time = 3,
    description = '<p>Explore pitch and listening with Vowel Phrase Families. Say the following phrases and then ask the group what the vowel sound is in each: ‘Doodle, noodle, poodle, toodle’ - Oo – sing this vowel on a….</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Say the following phrases and then ask the group what the vowel sound is in each: ‘Doodle, noodle, poodle, toodle’ - Oo – sing this vowel on a monotone over 8 beats with a crescendo then a diminuendo or make up a vocal pattern starting with 1,2,3,4,5,4,3,2,1. ‘Bosh, dosh, josh, posh, nosh’ – or ‘Sahara, aardvark, car park’ – ah ‘Bear, lair, Clare, rare, mare’ – air ‘Heebie-jeebies, TV freebies’ – ee.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>On vowel changes in Vowel Phrase Families, keep the jaw released; spot-check one row if sounds collapse into a muffled schwa.</li><li>On Vowel Phrase Families, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Resolve Vowel Phrase Families onto a comfortable mid-range hum before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '101c515d-4dc9-408c-98a8-8abfaeb06fc2';

-- [Pitch Exercises] 5-Note Scale Word Sets
UPDATE activities
SET activity = '5-Note Scale Word Sets',
    time = 3,
    description = '<p>Explore pitch and listening with 5-Note Scale Word Sets. Sing up and down a 5 note scale to ‘la’, ‘loo’, ‘see-saw’, ‘bella’, ‘dinner’ &amp; ‘rhubarb’.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Sing up and down a 5 note scale to ‘la’, ‘loo’, ‘see-saw’, ‘bella’, ‘dinner’ &amp; ‘rhubarb’.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of 5-Note Scale Word Sets; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On 5-Note Scale Word Sets, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After 5-Note Scale Word Sets, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '2a0ca983-b8ee-49b1-9877-8c22ca7ca80a';

-- [Pitch Exercises] Vowel Arpeggios
UPDATE activities
SET activity = 'Vowel Arpeggios',
    time = 3,
    description = '<p>Explore pitch and listening with Vowel Arpeggios. Practice the following vowel sounds ‘A’ for ‘apple’, ‘Ee’ for ‘Electricity’, ‘Eh’ for ‘ABC’, ‘O’ for ‘Awful’, ‘O’ for ‘Oh dear’ and ‘Oo’ for….</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Practice the following vowel sounds ‘A’ for ‘apple’, ‘Ee’ for ‘Electricity’, ‘Eh’ for ‘ABC’, ‘O’ for ‘Awful’, ‘O’ for ‘Oh dear’ and ‘Oo’ for ‘Oozing’ on an arpeggio.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Vowel Arpeggios; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On vowel changes in Vowel Arpeggios, keep the jaw released; spot-check one row if sounds collapse into a muffled schwa.</li><li>After Vowel Arpeggios, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '42ee0210-8425-4d54-a0c7-d502a532ce95';

-- [Pitch Exercises] Department Store Lift
UPDATE activities
SET activity = 'Department Store Lift',
    time = 3,
    description = '<p>Explore pitch and listening with Department Store Lift. Imagine they are in a lift in a big department store starting off in the basement with their lowest voice and then gradually moving up to the 10th….</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Imagine they are in a lift in a big department store starting off in the basement with their lowest voice and then gradually moving up to the 10th floor.</li><li>Choose a different vowel sound each time and come down.</li></ol><p><strong>Teacher tips</strong></p><ul><li>On vowel changes in Department Store Lift, keep the jaw released; spot-check one row if sounds collapse into a muffled schwa.</li><li>On Department Store Lift, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After Department Store Lift, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'e3dccadb-ce92-4425-af7e-d9b36e16571c';

-- [Pitch Exercises] Lottery Mm Chances
UPDATE activities
SET activity = 'Lottery Mm Chances',
    time = 3,
    description = '<p>Explore pitch and listening with Lottery Mm Chances. Ask them to imagine that someone has said to them that they have a 25% chance of winning the National Lottery – do a vocal ‘mmm’ going up and down a….</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Ask them to imagine that someone has said to them that they have a 25% chance of winning the National Lottery – do a vocal ‘mmm’ going up and down a little bit.</li><li>Then they are told that they have a 50% chance of winning – the ‘mmm’ goes up a little further.</li><li>Then they are told they have a 95% chance of winning – the ‘mmm’ goes up and down even higher.</li><li>Put all three sounds together.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Aim for a continuous buzz in Lottery Mm Chances with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>On Lottery Mm Chances, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Resolve Lottery Mm Chances onto a comfortable mid-range hum before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'e7e2b36b-585e-46aa-8a7c-5ec13bf07638';

-- [Pitch Exercises] Window Sound Effects
UPDATE activities
SET activity = 'Window Sound Effects',
    time = 3,
    description = '<p>Explore pitch and listening with Window Sound Effects. What might you hear through the window?.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>What might you hear through the window?</li><li>A police siren; Ambulance (lower); motor bike in the distance getting nearer; birds song.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Aim for a continuous buzz in Window Sound Effects with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>On Window Sound Effects, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After Window Sound Effects, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '7000ed59-e0a3-45f9-b904-67b01713f6f7';

-- [Pitch Exercises] Elastic Band Note
UPDATE activities
SET activity = 'Elastic Band Note',
    time = 3,
    description = '<p>Explore pitch and listening with Elastic Band Note. Imagine there is an elastic band attached to the ceiling with a note on it.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Imagine there is an elastic band attached to the ceiling with a note on it.</li><li>They are to pull the elastic band slowly down and then let it go quickly.</li><li>Start on the sound ‘ng’, then an ‘ee’ then ‘ah’ sound.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Aim for a continuous buzz in Elastic Band Note with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>On Elastic Band Note, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After Elastic Band Note, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '5d78fcf9-78d4-4ee5-8edb-5980fd0e79ac';

-- [Pitch Exercises] Move Up Scale
UPDATE activities
SET activity = 'Move Up Scale',
    time = 3,
    description = '<p>Explore pitch and listening with Move Up Scale. Sing up the scale ‘1 2 3 4 5 4 3 2 1’ followed by a clap and the leader singing ‘Move up’ so the scale can be sung again a semitone higher.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Sing up the scale ‘1 2 3 4 5 4 3 2 1’ followed by a clap and the leader singing ‘Move up’ so the scale can be sung again a semitone higher.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Move Up Scale; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On Move Up Scale, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After Move Up Scale, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '9ad5fc9f-b183-406c-9ca3-a190093256ba';

-- [Pitch Exercises] Choose and Change Scale Numbers
UPDATE activities
SET activity = 'Choose and Change Scale Numbers',
    time = 3,
    description = '<p>Explore pitch and listening with Choose and Change Scale Numbers. Sing slowly up the scale from 1 – 8.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sing slowly up the scale from 1 – 8.</li><li>Then repeat but ask each child to choose a number and hold on to that number without wavering and being put off by those around them.</li><li>Repeat the activity but this time change to another number of the scale, singing that number when ‘change’ is called out.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Choose and Change Scale Numbers; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On Choose and Change Scale Numbers, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Finish Choose and Change Scale Numbers descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '42393163-f8f4-43c6-b3fa-370190ee88f7';

-- [Pitch Exercises] 12345 Pattern
UPDATE activities
SET activity = '12345 Pattern',
    time = 3,
    description = '<p>Explore pitch and listening with 12345 Pattern. Sing ‘1234543212345432123454321 5 1’.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sing ‘1234543212345432123454321 5 1’.</li><li>Then repeat a semitone higher and so on.</li><li>Change the sound to ‘Doo’ then ‘Nah’.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of 12345 Pattern; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On 12345 Pattern, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After 12345 Pattern, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '756e6a00-d51b-4fe1-8f22-c91a4b07d88d';

-- [Pitch Exercises] Sing 5-4-3-2-1
UPDATE activities
SET activity = 'Sing 5-4-3-2-1',
    time = 3,
    description = '<p>Explore pitch and listening with Sing 5-4-3-2-1. Sing the word ‘Sing’ moving straight on to the ‘ng’ to the notes 5, 4, 3, 2, 1 of the scale then moving up 2, 3, 4, with an ‘ee’ sound on notes 5, 3….</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Sing the word ‘Sing’ moving straight on to the ‘ng’ to the notes 5, 4, 3, 2, 1 of the scale then moving up 2, 3, 4, with an ‘ee’ sound on notes 5, 3 and 1.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Aim for a continuous buzz in Sing 5-4-3-2-1 with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>Give a clear starting pitch each repeat of Sing 5-4-3-2-1; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>After Sing 5-4-3-2-1, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '4d1101ef-88fe-4ebf-99bf-076d23d47c25';

-- [Pitch Exercises] Zinger
UPDATE activities
