-- [Pitch Exercises] Puppy and Trampoline
UPDATE activities
SET activity = 'Puppy and Trampoline',
    time = 3,
    description = '<p>Explore pitch and listening with Puppy and Trampoline. Pretend that you have a little puppy that won’t stop whining.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Pretend that you have a little puppy that won’t stop whining.</li><li>You get fed up with it and throw it out of the window.</li><li>Fortunately, there is a trampoline below which it bounces up and down on.</li></ol><p><strong>Teacher tips</strong></p><ul><li>On Puppy and Trampoline, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Finish Puppy and Trampoline descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '2b23acfd-f7ad-4fdd-8328-c9180e5ca5ca';

-- [Pitch Exercises] Ng to Ah Octave Siren
UPDATE activities
SET activity = 'Ng to Ah Octave Siren',
    time = 3,
    description = '<p>Explore pitch and listening with Ng to Ah Octave Siren. Siren up a 5th or an octave to an ‘ng’ sound and then slide down to an ‘Ah’ sound.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Siren up a 5th or an octave to an ‘ng’ sound and then slide down to an ‘Ah’ sound.</li><li>Repeat moving up a semitone each time.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Aim for a continuous buzz in Ng to Ah Octave Siren with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>Give a clear starting pitch each repeat of Ng to Ah Octave Siren; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>After Ng to Ah Octave Siren, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '86d431a0-d319-404b-a13b-b4bad115ad19';

-- [Pitch Exercises] Chord from Number Pattern
UPDATE activities
SET activity = 'Chord from Number Pattern',
    time = 3,
    description = '<p>Explore pitch and listening with Chord from Number Pattern. Sing the notes of the scale to numbers in this progression – 1, 2, 3, (slowly) 1, 2, 3, 4, 5 (quicker) then 1, 8, 5, 3, 1.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sing the notes of the scale to numbers in this progression – 1, 2, 3, (slowly) 1, 2, 3, 4, 5 (quicker) then 1, 8, 5, 3, 1.</li><li>When confident with this divide the group into 4 parts and give each part a note to hold on to, to form a chord – 8, 5, 3, 1.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Chord from Number Pattern; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On Chord from Number Pattern, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Resolve Chord from Number Pattern onto a comfortable mid-range hum before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '2953d308-ac05-40aa-b525-8e4a48c6ef9f';

-- [Pitch Exercises] Puppy to Seagull Slides
