SET activity = 'Puppy to Seagull Slides',
    time = 3,
    description = '<p>Explore pitch and listening with Puppy to Seagull Slides. With the eyes and mouth closed, whine like a puppy.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>With the eyes and mouth closed, whine like a puppy.</li><li>Keeping that sound, slide slowly but smoothly down to the lowest point of your range and hold.</li><li>Slide back up in the same fashion.</li><li>Repeat to a short, repetitive ‘caw’, like a seagull.</li></ol><p><strong>Teacher tips</strong></p><ul><li>On Puppy to Seagull Slides, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After Puppy to Seagull Slides, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '507cc756-7e13-4ab6-a3c3-b078b6673bef';

-- [Pitch Exercises] Breathy to Focused Ah
UPDATE activities
SET activity = 'Breathy to Focused Ah',
    time = 3,
    description = '<p>Explore pitch and listening with Breathy to Focused Ah. Whisper an ‘ah’ to start, with no sound, then add a small amount of sound, to create a very breathy tone.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Whisper an ‘ah’ to start, with no sound, then add a small amount of sound, to create a very breathy tone.</li><li>Note that you are using a lot of air.</li><li>Now gradually focus the tone until you find a highly efficient, slightly harsh but very focused tone, which uses hardly any air at all.</li></ol><p><strong>Teacher tips</strong></p><ul><li>On Breathy to Focused Ah, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After Breathy to Focused Ah, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '13f5d3ed-3a69-46f1-ad2f-3d71fce306d7';

-- [Pitch Exercises] 5-Note Scale with Low 5
UPDATE activities
SET activity = '5-Note Scale with Low 5',
    time = 3,
    description = '<p>Explore pitch and listening with 5-Note Scale with Low 5. Sing the first 5 notes of the scale going up then down, followed by singing 1 &amp; low 5 to minims followed by a semibreve on 1.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sing the first 5 notes of the scale going up then down, followed by singing 1 &amp; low 5 to minims followed by a semibreve on 1.</li><li>Repeat moving up a semitone each time.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of 5-Note Scale with Low 5; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On 5-Note Scale with Low 5, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Resolve 5-Note Scale with Low 5 onto a comfortable mid-range hum before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '8c654354-fc33-4846-80dc-78983017f3d8';

-- [Pitch Exercises] Vizzery Vazzery Vem
UPDATE activities
SET activity = 'Vizzery Vazzery Vem',
    time = 3,
    description = '<p>Explore pitch and listening with Vizzery Vazzery Vem. Use the rhyme ‘Vizzery, vazzery, vozzery, Vem.’ Split the group into 3 parts.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Use the rhyme ‘Vizzery, vazzery, vozzery, Vem.’ Split the group into 3 parts.</li><li>Part 1 sings the words on C, then add Part on E and finally Part 3 on G.</li></ol><p><strong>Teacher tips</strong></p><ul><li>On Vizzery Vazzery Vem, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After Vizzery Vazzery Vem, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '36d7b98a-3fec-49d0-be82-efc1e917ba73';

-- [Pitch Exercises] Cowboy Lasso Yee-Hi
UPDATE activities
SET activity = 'Cowboy Lasso Yee-Hi',
    time = 3,
    description = '<p>Explore pitch and listening with Cowboy Lasso Yee-Hi. Imagine you are a cowboy on an American ranch about to catch a bull with your lasso.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Imagine you are a cowboy on an American ranch about to catch a bull with your lasso.</li><li>Pretend to throw your lasso, and call out ‘Yee-hi!’ with a high, twangy voice.</li><li>You catch your imaginary bull first time, and so you punch your fist and call out ‘Yo’ in a deep voice.</li></ol><p><strong>Teacher tips</strong></p><ul><li>On Cowboy Lasso Yee-Hi, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Finish Cowboy Lasso Yee-Hi descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '12d5c04f-ca40-4907-865b-a11773615cfe';

-- [Pitch Exercises] Cowboy Story Sound Effects
UPDATE activities
SET activity = 'Cowboy Story Sound Effects',
    time = 3,
    description = '<p>Explore pitch and listening with Cowboy Story Sound Effects. Read the following story to the group with them putting in the sound effects: ‘Let me introduce you to some friends of mine who like to go riding.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Read the following story to the group with them putting in the sound effects: ‘Let me introduce you to some friends of mine who like to go riding.</li><li>I have a friend called a cowboy.</li><li>My cowboy says ‘Yee hah’.</li><li>You say ‘Yee hah’.</li><li>Match an action to each sound – cowboy throwing a lasso.</li></ol><p><strong>Teacher tips</strong></p><ul><li>If the lip buzz in Cowboy Story Sound Effects won’t start, add a tiny voiced ‘b’ or ‘v’ underneath — never force dry lips.</li><li>Aim for a continuous buzz in Cowboy Story Sound Effects with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>Resolve Cowboy Story Sound Effects onto a comfortable mid-range hum before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '016f3586-124d-4ad9-8064-bc4fe2113d9f';

-- [Pitch Exercises] Space Warm-Up
UPDATE activities
SET activity = 'Space Warm-Up',
    time = 3,
    description = '<p>Explore pitch and listening with Space Warm-Up. ‘Space warm-up’: Build up the following parts one by one: 1.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>‘Space warm-up’: Build up the following parts one by one: 1.</li><li>Click on the off-beat then say 5, click, 4, click, 3, 2, (click), 1, lift off (click). 2. ‘I can’t hear you, do you read me, (‘kee’), you’re breaking up’ (throat sound ‘kee’ with tongue at the roof of mouth) 1st time all sung on a monotone on the note C.</li><li>Second time the phrase is sung the tune moves up to a G on the words ‘hear you’ and ‘read me’.</li><li>Have your hand by your ear as if trying to hear someone. 3. ‘Rock, rock, rock, I’m in a rocket.</li><li>Rock, rock, rock, lift off’, spoken in a syncopated rhythm and in a posh voice as if they are Prince Charles.</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Space Warm-Up, exaggerate tip-of-tongue consonants slowly first; only speed up when every syllable stays clear.</li><li>Alternate sound effects in Space Warm-Up with a recovery breath so the class doesn’t get dizzy.</li><li>Resolve Space Warm-Up onto a comfortable mid-range hum before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '447a8589-9e2b-4b0f-ac6b-c13d7fde560e';

-- [Pitch Exercises] Captain Jack Left Right
UPDATE activities
SET activity = 'Captain Jack Left Right',
    time = 3,
    description = '<p>Explore pitch and listening with Captain Jack Left Right. Chant ‘left, left’ slowly and step the left foot on the floor.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Chant ‘left, left’ slowly and step the left foot on the floor.</li><li>Then move to ‘left, right, left’.</li><li>Then say ‘Left, right, up in the air’.</li><li>Then back to ‘left, right, left’.</li><li>Then ‘left, right, up in the air, left, right, left’.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Captain Jack Left Right; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On Captain Jack Left Right, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Resolve Captain Jack Left Right onto a comfortable mid-range hum before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'a58c5378-1e96-4e4f-8025-11cda8c16ff2';

-- [Pitch Exercises] Chocolate 9-Syllable Hums
UPDATE activities
SET activity = 'Chocolate 9-Syllable Hums',
    time = 3,
    description = '<p>Explore pitch and listening with Chocolate 9-Syllable Hums. Gently hum five notes up and down (9 notes in all).</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gently hum five notes up and down (9 notes in all).</li><li>Change to a vowel and choose a new starting note.</li><li>Think of phrases or sentences about chocolate to sing to this 9 syllable tune eg. ‘Chocolate is runny when it melts’.</li><li>‘Squares are nice but Buttons suit me best’.</li><li>Invite soloists to sing this in a call &amp; response fashion.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Aim for a continuous buzz in Chocolate 9-Syllable Hums with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>On vowel changes in Chocolate 9-Syllable Hums, keep the jaw released; spot-check one row if sounds collapse into a muffled schwa.</li><li>After Chocolate 9-Syllable Hums, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '33215c04-6ef7-4f47-a1ba-a1c6bcef9a3e';

-- [Pitch Exercises] Ng Resonance to Ah
UPDATE activities
SET activity = 'Ng Resonance to Ah',
    time = 3,
    description = '<p>Explore pitch and listening with Ng Resonance to Ah. Say the word ‘sing’ and then hum a gentle siren on ‘ng’ from low to high and back down again (check that eyebrows are helping at the upper end!)….</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Say the word ‘sing’ and then hum a gentle siren on ‘ng’ from low to high and back down again (check that eyebrows are helping at the upper end!) Place hands on their chest and feel the change in resonance as the voice moves up into head voice and down into chest register.</li><li>Change this to an open ‘Ah’, ensuring no chins rise and that shoulders and hands are still relaxed.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Aim for a continuous buzz in Ng Resonance to Ah with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>On Ng Resonance to Ah, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Resolve Ng Resonance to Ah onto a comfortable mid-range hum before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '674319e9-9129-4937-b8ec-6f1d69fc6b56';

-- [Pitch Exercises] There’s a White Van Man
UPDATE activities
SET activity = 'There’s a White Van Man',
    time = 3,
    description = '<p>Explore pitch and listening with There’s a White Van Man. Speak the words of the warm-up ‘There’s a white van man’ and then sing it coming down the scale.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Speak the words of the warm-up ‘There’s a white van man’ and then sing it coming down the scale.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of There’s a White Van Man; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On There’s a White Van Man, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Finish There’s a White Van Man descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '8cd46ada-8540-44e9-9634-9e3d110a83d9';

-- [Pitch Exercises] Toyota Mitsubishi Nissan
UPDATE activities
SET activity = 'Toyota Mitsubishi Nissan',
    time = 3,
    description = '<p>Explore pitch and listening with Toyota Mitsubishi Nissan. Say the words ‘Toyota’, ‘Mitsubishi’ and ‘Nissan’ to different pitches.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Encourages bold but controlled vocal play</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Say the words ‘Toyota’, ‘Mitsubishi’ and ‘Nissan’ to different pitches.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>On Toyota Mitsubishi Nissan, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Finish Toyota Mitsubishi Nissan descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Widen the range, add a dynamic swell, or run as a short canon.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'a7d5bdf4-61b4-41b9-b1fe-fabc3dcdbca2';

