-- [Pitch Exercises] Diving Board
UPDATE activities
SET activity = 'Diving Board',
    time = 3,
    description = '<p>Explore pitch and listening with Diving Board. Play ‘Diving board’.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Play ‘Diving board’.</li><li>Imagine they are on the top board at the swimming pool.</li><li>Stretch their arm and finger as high as they can to indicate this.</li><li>Find the highest, gentle note in their voice, and dive off the board, sliding the voice down as they approach the water, using the full range of their voice.</li><li>Add a deep ‘Splash’ at the end.</li></ol><p><strong>Teacher tips</strong></p><ul><li>On Diving Board, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After Diving Board, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'f0242800-ac98-423e-a6e9-a698f1d5fb26';

-- [Pitch Exercises] Bite a Bun / Wear a Wig
UPDATE activities
SET activity = 'Bite a Bun / Wear a Wig',
    time = 3,
    description = '<p>Explore pitch and listening with Bite a Bun / Wear a Wig. To the tune of the ‘William Tell’ overture sing the words ‘Bite a bun!’ and then ‘Wear a wig!’ and finally ‘Touch your toes!’ Come up with their own….</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>To the tune of the ‘William Tell’ overture sing the words ‘Bite a bun!’ and then ‘Wear a wig!’ and finally ‘Touch your toes!’ Come up with their own tongue twisters to sing.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>For Bite a Bun / Wear a Wig, exaggerate tip-of-tongue consonants slowly first; only speed up when every syllable stays clear.</li><li>On Bite a Bun / Wear a Wig, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Finish Bite a Bun / Wear a Wig descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '5e3cab71-4d8a-4813-8549-3a30f3537658';

