-- [Pitch Exercises] Arkmalia Ekmalia Ootmoolia
UPDATE activities
SET activity = 'Arkmalia Ekmalia Ootmoolia',
    time = 3,
    description = '<p>Explore pitch and listening with Arkmalia Ekmalia Ootmoolia. Imagine they are visiting the country of ‘Arkmalia’ where the people are tired all the time.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Imagine they are visiting the country of ‘Arkmalia’ where the people are tired all the time.</li><li>Sing the sentence ‘I like to eat’ to an arpeggio pattern, yawning whilst they sing.</li><li>Next you visit the country next door called ‘Ekmalia’, where the people are very happy.</li><li>Sing the sentence again but happily.</li><li>Then you visit the small country of ‘Ootmoolia’ where the people are very romantic, so sing with their lips forward.</li></ol><p><strong>Teacher tips</strong></p><ul><li>If the lip buzz in Arkmalia Ekmalia Ootmoolia won’t start, add a tiny voiced ‘b’ or ‘v’ underneath — never force dry lips.</li><li>Give a clear starting pitch each repeat of Arkmalia Ekmalia Ootmoolia; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>Resolve Arkmalia Ekmalia Ootmoolia onto a comfortable mid-range hum before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '3984c833-7959-45bc-902c-384408d92d0c';

-- [Pitch Exercises] Scale with Breath Rest
UPDATE activities
SET activity = 'Scale with Breath Rest',
    time = 3,
    description = '<p>Explore pitch and listening with Scale with Breath Rest. Revise singing up and down the 5 note scale.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Revise singing up and down the 5 note scale.</li><li>Then try with a complete scale, with a 4 beat rest in the middle for a breath.</li><li>Then try singing 1,2,1,3,1,4,1,5,5,4,5,3,5,2,5,1.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Scale with Breath Rest; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On Scale with Breath Rest, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Resolve Scale with Breath Rest onto a comfortable mid-range hum before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '6ca75f50-9cca-42dd-aff5-4fbb37d3bb18';

-- [Pitch Exercises] Drone and Scale
UPDATE activities
SET activity = 'Drone and Scale',
    time = 3,
    description = '<p>Explore pitch and listening with Drone and Scale. Sing up and down a major scale or a pentatonic scale.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sing up and down a major scale or a pentatonic scale.</li><li>Have half the group sing the first note of the scale and hold it as a drone while the other half sing slowly up the scale to the sound ‘oo’.</li><li>Listen to the effect then swap over.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Drone and Scale; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On Drone and Scale, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After Drone and Scale, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'e3105002-b942-4e95-b4c1-d0115301ffd5';

-- [Pitch Exercises] 3-Part Tuning on D
UPDATE activities
SET activity = '3-Part Tuning on D',
    time = 3,
    description = '<p>Explore pitch and listening with 3-Part Tuning on D. Practice a tuning exercise, where the group is divided into 3.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Practice a tuning exercise, where the group is divided into 3.</li><li>Give each group a note to sing from the chord of D.</li><li>Sing the notes to hum.</li><li>Encourage them to hold their note whilst being aware of the other two notes of the chord.</li><li>At a given signal, open this sound out to an ‘Ah’.</li></ol><p><strong>Teacher tips</strong></p><ul><li>For 3-Part Tuning on D, exaggerate tip-of-tongue consonants slowly first; only speed up when every syllable stays clear.</li><li>Aim for a continuous buzz in 3-Part Tuning on D with almost no air leak; if tone thins, drop the range and widen the smile slightly.</li><li>Finish 3-Part Tuning on D descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '08d54111-fa9e-45c0-8da0-1fb3f1106741';

-- [Pitch Exercises] Mmm to Maw
UPDATE activities
SET activity = 'Mmm to Maw',
    time = 3,
    description = '<p>Explore pitch and listening with Mmm to Maw. Sing ‘mmm’ on one note over 4 beats and then open up to ‘maw’.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sing ‘mmm’ on one note over 4 beats and then open up to ‘maw’.</li><li>Try any vowel on the end.</li></ol><p><strong>Teacher tips</strong></p><ul><li>On vowel changes in Mmm to Maw, keep the jaw released; spot-check one row if sounds collapse into a muffled schwa.</li><li>On Mmm to Maw, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Resolve Mmm to Maw onto a comfortable mid-range hum before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '42765c9d-b2f2-4399-8933-449a808aac15';

-- [Pitch Exercises] Bungee Jumping
UPDATE activities
SET activity = 'Bungee Jumping',
    time = 3,
    description = '<p>Explore pitch and listening with Bungee Jumping. Play ‘Bungee jumping’ with the voice.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Play ‘Bungee jumping’ with the voice.</li><li>Say ‘Weeeh!’ starting as high in their voice as they can and sliding down as low as their voice will go.</li></ol><p><strong>Teacher tips</strong></p><ul><li>On Bungee Jumping, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After Bungee Jumping, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'cc169cda-2190-4f28-b9c6-e842a2cbdd82';

-- [Pitch Exercises] Legato Loo Phrase
UPDATE activities
SET activity = 'Legato Loo Phrase',
    time = 3,
    description = '<p>Explore pitch and listening with Legato Loo Phrase. Aim for legato singing.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Aim for legato singing.</li><li>Sing a long phrase from a song they are working on to the sound ‘loo’.</li><li>As they sing, trace rainbow shapes in the air with their arms, or mime sewing with a very long needle and thread.</li><li>Then repeat but singing the correct words to the phrase.</li></ol><p><strong>Teacher tips</strong></p><ul><li>On Legato Loo Phrase, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Finish Legato Loo Phrase descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '6c539efd-cd41-49f6-ab15-537b6effe089';

-- [Pitch Exercises] Head Voice Letter Box
UPDATE activities
SET activity = 'Head Voice Letter Box',
    time = 3,
    description = '<p>Explore pitch and listening with Head Voice Letter Box. To explore their head voice, imagine a piece of string attached to the back of their head.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>To explore their head voice, imagine a piece of string attached to the back of their head.</li><li>Pull the string out sing a broken arpeggio coming down, then raise up a semitone with another piece of string and so on.</li><li>Aim to ‘post’ each note clearly through the letter box.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Head Voice Letter Box; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On Head Voice Letter Box, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Finish Head Voice Letter Box descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'a43b7950-86ac-4e89-9d68-db8ac91eb889';

