UPDATE activities
SET activity = 'Known Song on Vowels',
    time = 3,
    description = '<p>Explore pitch and listening with Known Song on Vowels. Vowels carry the expression, tone and power in singing.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Vowels carry the expression, tone and power in singing.</li><li>Sing a known song only on the vowels.</li><li>Only 5 main vowel sounds (ee eh ah oh oo).</li></ol><p><strong>Teacher tips</strong></p><ul><li>On vowel changes in Known Song on Vowels, keep the jaw released; spot-check one row if sounds collapse into a muffled schwa.</li><li>On Known Song on Vowels, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Finish Known Song on Vowels descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'fb528a99-73b7-4cd2-bfa5-bfaa48665dd0';

-- [Pitch Exercises] Crescendo Descending Scale
UPDATE activities
SET activity = 'Crescendo Descending Scale',
    time = 3,
    description = '<p>Explore pitch and listening with Crescendo Descending Scale. Sing a crescendo and diminuendo on each note of a descending scale passage using a range of vowel shapes.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Sing a crescendo and diminuendo on each note of a descending scale passage using a range of vowel shapes.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Crescendo Descending Scale; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On vowel changes in Crescendo Descending Scale, keep the jaw released; spot-check one row if sounds collapse into a muffled schwa.</li><li>After Crescendo Descending Scale, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '4f680e19-173c-4c54-8e03-c8405d4da855';

-- [Pitch Exercises] Vocal Colour Palette
UPDATE activities
SET activity = 'Vocal Colour Palette',
    time = 3,
    description = '<p>Explore pitch and listening with Vocal Colour Palette. Explain that just as in painting you can create many different colours and shades that express a mood with the human voice, therefore creating a….</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Explain that just as in painting you can create many different colours and shades that express a mood with the human voice, therefore creating a palette of many different vocal ‘colours’.</li><li>For example: 1.</li><li>Sing as if you are speaking (called speech quality).</li><li>You will hear this quality in pop and music theatre songs.</li><li>If you try to sing too high, however, it will feel very uncomfortable and sound shouted and strained.</li></ol><p><strong>Teacher tips</strong></p><ul><li>On Vocal Colour Palette, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After Vocal Colour Palette, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '8ab72dce-6daf-445d-a323-122d0e76ca60';

-- [Pitch Exercises] Over the Rainbow Voices
UPDATE activities
SET activity = 'Over the Rainbow Voices',
    time = 3,
    description = '<p>Explore pitch and listening with Over the Rainbow Voices. Sing the first 4 bars of ‘Over the Rainbow’ in the following voices: 1.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sing the first 4 bars of ‘Over the Rainbow’ in the following voices: 1.</li><li>Sing it as grand opera (find the Pavarotti feeling in the diaphragm.) 2.</li><li>Sing it as the witch in ‘The Wizard of Oz’ (find the twang in the nose.) 3.</li><li>Sing it as a cockney market trader. 4.</li><li>Sing it as the Walt Disney princess.</li></ol><p><strong>Teacher tips</strong></p><ul><li>During Over the Rainbow Voices, hands on ribs/tummy stay light — expansion should be sideways/forwards, not a heaved chest.</li><li>On Over the Rainbow Voices, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Finish Over the Rainbow Voices descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '17de5be9-e094-4823-9b9c-6d7f1712aed7';

-- [Pitch Exercises] Somewhere Over the Rainbow Rise
UPDATE activities
SET activity = 'Somewhere Over the Rainbow Rise',
    time = 3,
    description = '<p>Explore pitch and listening with Somewhere Over the Rainbow Rise. Sing the first line of ‘Somewhere over the rainbow’ rising in pitch a semitone each time.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Sing the first line of ‘Somewhere over the rainbow’ rising in pitch a semitone each time.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Somewhere Over the Rainbow Rise; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On Somewhere Over the Rainbow Rise, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After Somewhere Over the Rainbow Rise, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '8d3fa466-e366-48e7-82b3-26da0ef21691';

-- [Pitch Exercises] Pentatonic Note Cards
UPDATE activities
SET activity = 'Pentatonic Note Cards',
    time = 3,
    description = '<p>Explore pitch and listening with Pentatonic Note Cards. Prepare a set of cards with the following music notes from the C pentatonic scale: C D E G A and a set of cards containing vocal sounds eg.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Prepare a set of cards with the following music notes from the C pentatonic scale: C D E G A and a set of cards containing vocal sounds eg.</li><li>Ooo mee aah.</li><li>Put the note cards into a bag and invite a child to pick out between 2 – 5 notes which will make up the tune that the chosen vowel sound will be sung to.</li><li>Pick the tune out on a tuned percussion instrument.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Pentatonic Note Cards; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>Sync Pentatonic Note Cards steps and clicks to a shared slow pulse before adding voice layers — clarity over speed.</li><li>On vowel changes in Pentatonic Note Cards, keep the jaw released; spot-check one row if sounds collapse into a muffled schwa.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '688b0b63-6dcf-4596-a83b-0effbfdbc9b6';

-- [Pitch Exercises] Vocal Percussion
UPDATE activities
SET activity = 'Vocal Percussion',
    time = 3,
    description = '<p>Explore pitch and listening with Vocal Percussion. Sing ‘Vocal percussion’ moving to the right and then left to a slow beat adding finger clicks on the off-beat.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sing ‘Vocal percussion’ moving to the right and then left to a slow beat adding finger clicks on the off-beat.</li><li>Try with ‘b’ ‘d’ ‘t’ and ‘p’.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Sync Vocal Percussion steps and clicks to a shared slow pulse before adding voice layers — clarity over speed.</li><li>On Vocal Percussion, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>After Vocal Percussion, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'a7f14bae-a23d-4028-b56e-e857b3cd71cf';

-- [Pitch Exercises] Forehead Chewing Gum Legato
UPDATE activities
SET activity = 'Forehead Chewing Gum Legato',
    time = 3,
    description = '<p>Explore pitch and listening with Forehead Chewing Gum Legato. To encourage legato sounds ask the children to imagine a long piece of chewing gum coming out of the middle of their forehead as they sing, which….</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>To encourage legato sounds ask the children to imagine a long piece of chewing gum coming out of the middle of their forehead as they sing, which carries all the words.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>In Forehead Chewing Gum Legato, keep the chew huge and silent for two beats before adding voice — floppy face, not clenched jaw.</li><li>Mime a long gum strand in Forehead Chewing Gum Legato — voices should feel pulled smoothly, never punched note to note.</li><li>Finish Forehead Chewing Gum Legato descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '4f0cd3da-dc4c-4836-9de8-c5ecff67978f';

-- [Pitch Exercises] Ee to Oh Scale and Whee
UPDATE activities
SET activity = 'Ee to Oh Scale and Whee',
    time = 3,
    description = '<p>Explore pitch and listening with Ee to Oh Scale and Whee. Sing up the first 4 notes of the scale to ‘ee’ then change the vowel to ‘oh’ for the 5th, 3rd, 4th, 2nd and back to the 1st note.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sing up the first 4 notes of the scale to ‘ee’ then change the vowel to ‘oh’ for the 5th, 3rd, 4th, 2nd and back to the 1st note.</li><li>Vary the vowels as they go.</li><li>To avoid tension, add a clap/’whee’ after each scale (‘whee’ is the falsetto sound you make when sliding down stairs).</li><li>The ‘whee’ will relax the vocal chords and prevent tension as you go up.</li><li>As you go higher, take deeper breaths.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Ee to Oh Scale and Whee; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On vowel changes in Ee to Oh Scale and Whee, keep the jaw released; spot-check one row if sounds collapse into a muffled schwa.</li><li>Finish Ee to Oh Scale and Whee descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '93785123-e649-41b5-9c79-b8579d58bf84';

-- [Pitch Exercises] I Can Sing Octave Leap
UPDATE activities
SET activity = 'I Can Sing Octave Leap',
    time = 3,
    description = '<p>Explore pitch and listening with I Can Sing Octave Leap. Sing the phrase ‘I can sing’ to the notes Bb Bb’ G Eb then B B’ G# E etc.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sing the phrase ‘I can sing’ to the notes Bb Bb’ G Eb then B B’ G# E etc. joining the first two notes on smoothly on the word ‘I’.</li><li>Aim for the octave leap to be like a fast glissando, to what is actually the syllable ‘ah’ with a brief ‘ih’ at the end.</li><li>Is the whole phrase balanced with the top note not sticking out?</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of I Can Sing Octave Leap; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On I Can Sing Octave Leap, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Resolve I Can Sing Octave Leap onto a comfortable mid-range hum before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '8515f181-10b0-4eaf-b011-3949b9628ce5';

-- [Pitch Exercises] Po-Pa-Ca-Ta-Pe-Tal
UPDATE activities
SET activity = 'Po-Pa-Ca-Ta-Pe-Tal',
    time = 3,
    description = '<p>Explore pitch and listening with Po-Pa-Ca-Ta-Pe-Tal. Sing the word ‘Po-pa-ca-ta-pe-tal’ on one note then up and down an 8 note scale.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Sing the word ‘Po-pa-ca-ta-pe-tal’ on one note then up and down an 8 note scale.</li><li>Then repeat but starting with ‘co-‘, ‘o-‘, ‘to-‘, ‘e-‘ and ‘a-‘.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Give a clear starting pitch each repeat of Po-Pa-Ca-Ta-Pe-Tal; if top notes shout, narrow to a gentle ‘ng’ slide first.</li><li>On vowel changes in Po-Pa-Ca-Ta-Pe-Tal, keep the jaw released; spot-check one row if sounds collapse into a muffled schwa.</li><li>After Po-Pa-Ca-Ta-Pe-Tal, sing the first phrase of the song on ‘ng’ using the same freedom.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'cf636d05-3a03-4aa3-964f-0946fae77c40';

-- [Pitch Exercises] Common Single Vowels
UPDATE activities
SET activity = 'Common Single Vowels',
    time = 3,
    description = '<p>Explore pitch and listening with Common Single Vowels. Here are the most common single vowels, ‘a’ (at), ‘ah’ (father), ‘aw’ (awful), ‘ay’ (hate), ‘ee’ (easy), ‘eh’ (every), ‘eye’ (eye), ‘ih’ (it), ‘oh’….</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Here are the most common single vowels, ‘a’ (at), ‘ah’ (father), ‘aw’ (awful), ‘ay’ (hate), ‘ee’ (easy), ‘eh’ (every), ‘eye’ (eye), ‘ih’ (it), ‘oh’ (know), ‘oo’ (moon), ‘uh’ (up).</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>On vowel changes in Common Single Vowels, keep the jaw released; spot-check one row if sounds collapse into a muffled schwa.</li><li>On Common Single Vowels, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Finish Common Single Vowels descending into speaking range so nobody carries tension upward.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = 'a3abb813-7001-4b13-aacb-6bdeb932d1d4';

-- [Pitch Exercises] Voice Walking
UPDATE activities
SET activity = 'Voice Walking',
    time = 3,
    description = '<p>Explore pitch and listening with Voice Walking. Play ‘Voice walking’ where the class follow one person’s hand going up, down, staying on the same level, to a sound of their choice.</p><p><strong>Why it works</strong></p><ul><li>Explores pitch range safely and playfully</li><li>Builds listening and pitch-matching accuracy</li><li>Smooths register transitions without pushing</li></ul>',
    activity_text = '<p><strong>Setup</strong></p><p>Standing circle or open rows facing the leader. Optional: piano or pitch reference. About 3 minutes.</p><p><strong>How to do it</strong></p><ol><li>Gather focus and watch the teacher model once in silence.</li><li>Play ‘Voice walking’ where the class follow one person’s hand going up, down, staying on the same level, to a sound of their choice.</li><li>Repeat together, then try once more with greater clarity.</li></ol><p><strong>Teacher tips</strong></p><ul><li>In Voice Walking, the leader’s hand must move smoothly — practise the gesture silently once so voices don’t jump.</li><li>On Voice Walking, isolate the hardest pitch gesture once, then rejoin the full pattern at a slower tempo.</li><li>Resolve Voice Walking onto a comfortable mid-range hum before repertoire.</li></ul><p><strong>Make it easier</strong></p><p>Narrow the pitch range and let the class echo the leader phrase by phrase.</p><p><strong>Make it harder</strong></p><p>Siren through a wider interval, then land softly on a sung ‘ah’.</p><p><strong>Extension</strong></p><p>Improvise a four-beat answer after the set pattern, still matching the leader’s vowel.</p>',
    updated_at = NOW()
WHERE id = '01df8aa5-68c7-41e5-be25-024737ffd928';

-- ----- Drama Games: teacher tips made exercise-specific -----

-- Drama tip refresh: Mirror Twins
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Clear floor space. Children work in pairs. No props needed. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>In pairs, one child moves slowly while the other mirrors exactly</li><li>Swap roles after 1-2 minutes</li></ol><p><strong>Teacher tips</strong></p><ul><li>If leaders race, freeze the pair and restart in exaggerated slow motion so mirrors can match.</li><li>In Mirror Twins, swap leaders halfway so both partners make offers, not just the confident one.</li><li>Scan the edges of the room in Mirror Twins and bring a quieter pupil in to lead the next micro-round.</li></ul><p><strong>Make it easier</strong></p><p>Work as a whole class first, then try with a partner.</p><p><strong>Make it harder</strong></p><p>Add a second cue (speed, size or emotion) once the basic game is secure.</p>',
    updated_at = NOW()
WHERE id = 'd17f19ed-9cf8-4547-9a40-69202d26c3ea';

-- Drama tip refresh: Yes, Let's!
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Clear floor space for movement. Whole class. No props needed. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>Leader calls ''Let''s [action]!'' (e.g. swim with whales)</li><li>Everyone replies ''Yes, let''s!'' and mimes the action together</li></ol><p><strong>Teacher tips</strong></p><ul><li>Before Yes, Let''s!, model the first ten seconds yourself so the rule is visible, not only explained.</li><li>Keep Yes, Let''s! to two short rounds; stop while faces are still bright and name one clear success.</li><li>Scan the edges of the room in Yes, Let''s! and bring a quieter pupil in to lead the next micro-round.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models first; children copy as a whole group before trying in pairs.</p><p><strong>Make it harder</strong></p><p>Demand clearer weight, size and texture so the audience can ''see'' the object.</p>',
    updated_at = NOW()
WHERE id = 'c3b8daa3-cc7e-49dc-9422-507b6f908bb5';

-- Drama tip refresh: Freeze Monster
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Clear floor space for movement. Props: optional music player. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>Play music for dancing</li><li>When music stops, children freeze in silly poses like monsters, superheroes, or trees</li></ol><p><strong>Teacher tips</strong></p><ul><li>Use one sharp freeze cue for Freeze Monster; hold three silent counts before you speak so stillness sticks.</li><li>Keep tracks short and fade early so freezes land on silence, not a long outro.</li><li>If Freeze Monster frays, shrink the group size for one round, then rebuild to whole class.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models first; children copy as a whole group before trying in pairs.</p><p><strong>Make it harder</strong></p><p>Add a second cue (speed, size or emotion) once the basic game is secure.</p>',
    updated_at = NOW()
WHERE id = 'f49e5a10-2320-4a8f-81ef-1e39aa6f05fd';

-- Drama tip refresh: Teleporting Environments
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Open floor space with clear pathways. No props needed. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>Children walk around pretending to be in specific places (desert, jungle, snowy mountain)</li><li>Shout ''TELEPORT!'' and name new location</li></ol><p><strong>Teacher tips</strong></p><ul><li>Before Teleporting Environments, model the first ten seconds yourself so the rule is visible, not only explained.</li><li>Keep Teleporting Environments to two short rounds; stop while faces are still bright and name one clear success.</li><li>Name one precise success after Teleporting Environments (‘clear freeze’, ‘brave offer’) before you reset.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models first; children copy as a whole group before trying in pairs.</p><p><strong>Make it harder</strong></p><p>Add a second cue (speed, size or emotion) once the basic game is secure.</p>',
    updated_at = NOW()
WHERE id = '80855026-ad93-4968-9135-a4e35f1ad892';

-- Drama tip refresh: Sculptors and Clay
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Clear floor space. Children work in pairs. No props needed. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>Ask the class to find a partner and face each other with a little space around them.</li><li>In pairs or groups, one child is sculptor and gently molds others into shapes or statues. Hold pose then swap roles.</li><li>Use a clear freeze cue; hold the picture, then relax and reset.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Use one sharp freeze cue for Sculptors and Clay; hold three silent counts before you speak so stillness sticks.</li><li>In Sculptors and Clay, swap leaders halfway so both partners make offers, not just the confident one.</li><li>If Sculptors and Clay frays, shrink the group size for one round, then rebuild to whole class.</li></ul><p><strong>Make it easier</strong></p><p>Work as a whole class first, then try with a partner.</p><p><strong>Make it harder</strong></p><p>Add a second cue (speed, size or emotion) once the basic game is secure.</p>',
    updated_at = NOW()
WHERE id = '22aa4be2-c256-4030-817a-bed3a281efea';

-- Drama tip refresh: Popcorn Gum
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Clear floor space for movement. No props needed. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>Mime putting gum in mouth, chew it bigger and bigger until it pops!</li><li>Add sound effects and exaggerate facial expressions</li></ol><p><strong>Teacher tips</strong></p><ul><li>Demand clear weight and size: if the audience can’t ‘see’ it, freeze and remime the first handle.</li><li>Keep Popcorn Gum to two short rounds; stop while faces are still bright and name one clear success.</li><li>Name one precise success after Popcorn Gum (‘clear freeze’, ‘brave offer’) before you reset.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models first; children copy as a whole group before trying in pairs.</p><p><strong>Make it harder</strong></p><p>Layer dynamics (loud/soft, near/far) and keep a shared pulse.</p>',
    updated_at = NOW()
WHERE id = '434bb402-d4c7-436f-b401-b1713543ef02';

-- Drama tip refresh: Alphabet Sounds
