-- Drama tip refresh: Emotion Walks
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Clear floor space for movement. No props needed. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>Walk like feeling an emotion in motion (''angry stomp'' or ''happy skip'')</li><li>Explore how emotions affect movement</li></ol><p><strong>Teacher tips</strong></p><ul><li>Name the emotion once, then coach body not face — ‘show it in your spine/hands’ keeps it performable.</li><li>Keep Emotion Walks to two short rounds; stop while faces are still bright and name one clear success.</li><li>If Emotion Walks frays, shrink the group size for one round, then rebuild to whole class.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models first; children copy as a whole group before trying in pairs.</p><p><strong>Make it harder</strong></p><p>Add a second cue (speed, size or emotion) once the basic game is secure.</p><p><strong>Extension</strong></p><p>Link to a story book face or feeling word of the day.</p>',
    updated_at = NOW()
WHERE id = '1d50693d-99a1-44a4-8aa6-275e049c6706';

