SET activity_text = '<p><strong>Setup</strong></p><p>Clear floor space for movement. No props needed. About 15 minutes.</p><p><strong>How to play</strong></p><ol><li>Taggers freeze others who must hold statue poses until unfrozen</li><li>Add themes like ''animal statues'' or ''happy statues''</li></ol><p><strong>Teacher tips</strong></p><ul><li>Use one sharp freeze cue for Statue Freeze Tag; hold three silent counts before you speak so stillness sticks.</li><li>Remind taggers to use gentle contact or a clear wink — no pushing or chasing into furniture.</li><li>Choose animals the class knows; cue changes with a clear word so transitions stay sharp, not chaotic.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models first; children copy as a whole group before trying in pairs.</p><p><strong>Make it harder</strong></p><p>Add a second cue (speed, size or emotion) once the basic game is secure.</p><p><strong>Extension</strong></p><p>Choose animals from a class topic or story.</p>',
    updated_at = NOW()
