-- Drama tip refresh: Story Circles
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Clear space so the class can sit or stand in a circle. No props needed. About 20 minutes.</p><p><strong>How to play</strong></p><ol><li>Children sit in circle and mime story episodes</li><li>After each segment, they verbally name what happened</li></ol><p><strong>Teacher tips</strong></p><ul><li>Demand clear weight and size: if the audience can’t ‘see’ it, freeze and remime the first handle.</li><li>Keep Story Circles to two short rounds; stop while faces are still bright and name one clear success.</li><li>If Story Circles frays, shrink the group size for one round, then rebuild to whole class.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models first; children copy as a whole group before trying in pairs.</p><p><strong>Make it harder</strong></p><p>Require a clear beginning, middle and end within the time limit.</p>',
    updated_at = NOW()
WHERE id = 'd04153e0-c208-4f53-a727-e514d04e7042';

-- Drama tip refresh: Magic Mirror
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Clear floor space for movement. No props needed. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>Gather attention and explain the game in one short sentence.</li><li>Children pretend to look into mirror and mimic facial expressions made by teacher or peer.</li><li>Repeat once or twice, celebrating clear choices, then stop while energy is still high.</li></ol><p><strong>Teacher tips</strong></p><ul><li>If leaders race, freeze the pair and restart in exaggerated slow motion so mirrors can match.</li><li>Keep Magic Mirror to two short rounds; stop while faces are still bright and name one clear success.</li><li>If Magic Mirror frays, shrink the group size for one round, then rebuild to whole class.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models first; children copy as a whole group before trying in pairs.</p><p><strong>Make it harder</strong></p><p>Add a second cue (speed, size or emotion) once the basic game is secure.</p>',
    updated_at = NOW()
WHERE id = 'b073d141-1b36-468e-a022-6acbf8512b69';

