-- Drama tip refresh: Emotion Telephone
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Clear space so the class can sit or stand in a circle. No props needed. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>Bring the class into a circle so everyone can see and hear.</li><li>Children whisper an emotion around circle; final child acts it out physically.</li><li>Repeat once or twice, celebrating clear choices, then stop while energy is still high.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Name the emotion once, then coach body not face — ‘show it in your spine/hands’ keeps it performable.</li><li>Keep the circle tight enough to hear; if the pass breaks, rewind two people and restart the chain.</li><li>Scan the edges of the room in Emotion Telephone and bring a quieter pupil in to lead the next micro-round.</li></ul><p><strong>Make it easier</strong></p><p>Teacher models first; children copy as a whole group before trying in pairs.</p><p><strong>Make it harder</strong></p><p>Add a second cue (speed, size or emotion) once the basic game is secure.</p><p><strong>Extension</strong></p><p>Link to a story book face or feeling word of the day.</p>',
    updated_at = NOW()
WHERE id = '384b21f8-def6-4d2c-8195-35a7c9eb3e97';

