-- Drama tip refresh: Ten-Second Objects
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Open floor space. Work in small groups. Groups of 3–5. No props needed. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>Organise the class into small groups and give them a clear playing space.</li><li>Small groups (3-5 children) sculpt bodies into named object within 10 seconds using only mime.</li><li>Play a second round with a fresh prompt, then share one strong moment with the class.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Demand clear weight and size: if the audience can’t ‘see’ it, freeze and remime the first handle.</li><li>After Ten-Second Objects, ask for one concrete example of good listening or a bold offer before you reset.</li><li>Name one precise success after Ten-Second Objects (‘clear freeze’, ‘brave offer’) before you reset.</li></ul><p><strong>Make it easier</strong></p><p>Reduce choices and model the first round together.</p><p><strong>Make it harder</strong></p><p>Demand clearer weight, size and texture so the audience can ''see'' the object.</p>',
    updated_at = NOW()
WHERE id = '1374a1c2-8844-4145-8b07-64d975790ebf';

