SET activity_text = '<p><strong>Setup</strong></p><p>Clear space so the class can sit or stand in a circle. No props needed. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>Circle counts 1-2-3 in sequence; on ''1'' stamp, ''2'' clap, ''3'' jump</li><li>Continue quickly building rhythm</li></ol><p><strong>Teacher tips</strong></p><ul><li>Before 1-2-3 Action Count, model the first ten seconds yourself so the rule is visible, not only explained.</li><li>After 1-2-3 Action Count, ask for one concrete example of good listening or a bold offer before you reset.</li><li>Scan the edges of the room in 1-2-3 Action Count and bring a quieter pupil in to lead the next micro-round.</li></ul><p><strong>Make it easier</strong></p><p>Reduce choices and model the first round together.</p><p><strong>Make it harder</strong></p><p>Add a time limit, a second rule, or ask pairs to share one polished moment.</p>',
    updated_at = NOW()
WHERE id = '380813ad-fc9f-4a57-a7a1-d395dda67e83';

-- Drama tip refresh: Daft Definitions
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Clear floor space. Children work in pairs. No props needed. About 15 minutes.</p><p><strong>How to play</strong></p><ol><li>In pairs, children invent silly meanings for everyday objects (e.g</li><li>''What''s a teapot?'' → ''It''s a singing elephant!''). Share with class</li></ol><p><strong>Teacher tips</strong></p><ul><li>Before Daft Definitions, model the first ten seconds yourself so the rule is visible, not only explained.</li><li>In Daft Definitions, swap leaders halfway so both partners make offers, not just the confident one.</li><li>Scan the edges of the room in Daft Definitions and bring a quieter pupil in to lead the next micro-round.</li></ul><p><strong>Make it easier</strong></p><p>Work as a whole class first, then try with a partner.</p><p><strong>Make it harder</strong></p><p>Add a time limit, a second rule, or ask pairs to share one polished moment.</p>',
    updated_at = NOW()
WHERE id = '28927533-c290-48ea-b71c-a6b10f6592ad';

