-- Drama tip refresh: Animal Characters
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Clear floor space for movement. No props needed. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>Gather attention and explain the game in one short sentence.</li><li>Children mime animals (using body and sound) while classmates guess what it is.</li><li>Take a few guesses, reveal the answer, then rotate so another child has a turn.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Demand clear weight and size: if the audience can’t ‘see’ it, freeze and remime the first handle.</li><li>Choose animals the class knows; cue changes with a clear word so transitions stay sharp, not chaotic.</li><li>Scan the edges of the room in Animal Characters and bring a quieter pupil in to lead the next micro-round.</li></ul><p><strong>Make it easier</strong></p><p>Reduce choices and model the first round together.</p><p><strong>Make it harder</strong></p><p>Layer dynamics (loud/soft, near/far) and keep a shared pulse.</p>',
    updated_at = NOW()
WHERE id = 'c96fe235-3ee5-4380-95a2-bec12df0fc44';

