    updated_at = NOW()
WHERE id = '3c9166d0-d0dc-4523-9131-27c5e7ede245';

-- Drama tip refresh: Sound Machines
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Clear floor space for movement. No props needed. About 15 minutes.</p><p><strong>How to play</strong></p><ol><li>Gather attention and explain the game in one short sentence.</li><li>Each student adds a simple, repetitive sound and motion to create a complex, evolving machine.</li><li>Play a second round with a fresh prompt, then share one strong moment with the class.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Each new part must connect physically to the last; pause to tighten rhythm before adding more pupils.</li><li>After Sound Machines, ask for one concrete example of good listening or a bold offer before you reset.</li><li>If Sound Machines frays, shrink the group size for one round, then rebuild to whole class.</li></ul><p><strong>Make it easier</strong></p><p>Reduce choices and model the first round together.</p><p><strong>Make it harder</strong></p><p>Layer dynamics (loud/soft, near/far) and keep a shared pulse.</p>',
    updated_at = NOW()
WHERE id = '24a6d616-1f3d-4eed-b280-a7aa33416d0d';

-- Drama tip refresh: Magic Cloak
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Clear floor space for movement. Props: hat and emotion slips. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>Children pretend to put on an imaginary cloak that gives them a new power or emotion (e.g. ''happy cloak'')</li><li>They then move and act accordingly</li></ol><p><strong>Teacher tips</strong></p><ul><li>Demand clear weight and size: if the audience can’t ‘see’ it, freeze and remime the first handle.</li><li>Name the emotion once, then coach body not face — ‘show it in your spine/hands’ keeps it performable.</li><li>Name one precise success after Magic Cloak (‘clear freeze’, ‘brave offer’) before you reset.</li></ul><p><strong>Make it easier</strong></p><p>Reduce choices and model the first round together.</p><p><strong>Make it harder</strong></p><p>Demand clearer weight, size and texture so the audience can ''see'' the object.</p>',
    updated_at = NOW()
WHERE id = 'c00458fc-b09a-4600-bc4a-a57a3934a4b5';

-- Drama tip refresh: Pass the Facial Expression
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Clear space so the class can sit or stand in a circle. No props needed. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>Pupils sit in a circle and one person makes a facial expression</li><li>The next person copies it and passes it on, without a sound</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep the circle tight enough to hear; if the pass breaks, rewind two people and restart the chain.</li><li>After Pass the Facial Expression, ask for one concrete example of good listening or a bold offer before you reset.</li><li>Scan the edges of the room in Pass the Facial Expression and bring a quieter pupil in to lead the next micro-round.</li></ul><p><strong>Make it easier</strong></p><p>Reduce choices and model the first round together.</p><p><strong>Make it harder</strong></p><p>Layer dynamics (loud/soft, near/far) and keep a shared pulse.</p>',
    updated_at = NOW()
WHERE id = '708a2401-d7d3-417e-bb23-d6eaa2989115';

-- Drama tip refresh: Freeze Frame Story
