SET activity_text = '<p><strong>Setup</strong></p><p>Clear floor space for movement. No props needed. About 20 minutes.</p><p><strong>How to play</strong></p><ol><li>Gather attention and explain the game in one short sentence.</li><li>The teacher tells a simple story, and at key moments, the pupils freeze to create a tableau (a still picture) of the scene.</li><li>Use a clear freeze cue; hold the picture, then relax and reset.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Use one sharp freeze cue for Freeze Frame Story; hold three silent counts before you speak so stillness sticks.</li><li>For Freeze Frame Story, allow one planning whisper only; then commit — stop the scene solely for safety or a clear reset.</li><li>If Freeze Frame Story frays, shrink the group size for one round, then rebuild to whole class.</li></ul><p><strong>Make it easier</strong></p><p>Reduce choices and model the first round together.</p><p><strong>Make it harder</strong></p><p>Require a clear beginning, middle and end within the time limit.</p><p><strong>Extension</strong></p><p>Bring one statue to life for five seconds, then freeze again.</p>',
    updated_at = NOW()
WHERE id = '68141294-e987-48cd-9531-945849928728';

-- Drama tip refresh: The Bus Stop
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Open floor space with clear pathways. Props: chairs. About 20 minutes.</p><p><strong>How to play</strong></p><ol><li>A ''bus stop'' is set up with chairs</li><li>Pupils take turns getting on and off the ''bus'', and in pairs or small groups, create a simple, improvised scene while waiting</li></ol><p><strong>Teacher tips</strong></p><ul><li>For The Bus Stop, allow one planning whisper only; then commit — stop the scene solely for safety or a clear reset.</li><li>In The Bus Stop, swap leaders halfway so both partners make offers, not just the confident one.</li><li>If The Bus Stop frays, shrink the group size for one round, then rebuild to whole class.</li></ul><p><strong>Make it easier</strong></p><p>Work as a whole class first, then try with a partner.</p><p><strong>Make it harder</strong></p><p>Require a clear beginning, middle and end within the time limit.</p>',
    updated_at = NOW()
WHERE id = 'f3404b89-9981-4014-84aa-ecd076f52fbd';

