-- Drama tip refresh: Emotional Obstacle Course
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Open floor space with clear pathways. No props needed. About 15 minutes.</p><p><strong>How to play</strong></p><ol><li>The teacher sets up an imaginary obstacle course</li><li>Pupils must navigate it while embodying a specific emotion (e.g. happily skipping over a river, angrily climbing a ladder)</li></ol><p><strong>Teacher tips</strong></p><ul><li>Demand clear weight and size: if the audience can’t ‘see’ it, freeze and remime the first handle.</li><li>Name the emotion once, then coach body not face — ‘show it in your spine/hands’ keeps it performable.</li><li>If Emotional Obstacle Course frays, shrink the group size for one round, then rebuild to whole class.</li></ul><p><strong>Make it easier</strong></p><p>Reduce choices and model the first round together.</p><p><strong>Make it harder</strong></p><p>Demand clearer weight, size and texture so the audience can ''see'' the object.</p>',
    updated_at = NOW()
WHERE id = 'e0edea28-221b-4d7a-8a16-2b2596f1e61e';

