UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Open floor space with clear pathways. No props needed. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>In pairs, one person is the ''camera'' and the other is the ''director''</li><li>The director moves the camera around the room and shouts ''Click!'' to take a picture of a frozen scene</li><li>The camera must ''take'' the picture by freezing in place</li></ol><p><strong>Teacher tips</strong></p><ul><li>For The Human Camera, allow one planning whisper only; then commit — stop the scene solely for safety or a clear reset.</li><li>In The Human Camera, swap leaders halfway so both partners make offers, not just the confident one.</li><li>Scan the edges of the room in The Human Camera and bring a quieter pupil in to lead the next micro-round.</li></ul><p><strong>Make it easier</strong></p><p>Work as a whole class first, then try with a partner.</p><p><strong>Make it harder</strong></p><p>Require a clear beginning, middle and end within the time limit.</p>',
