-- Drama tip refresh: Follow the Voice
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Open floor space with clear pathways. No props needed. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>Pupils close their eyes and listen as a ''leader'' walks around the room, making a specific sound</li><li>They must follow the sound without bumping into anyone</li></ol><p><strong>Teacher tips</strong></p><ul><li>Side-coach only with ‘accept and add’ — block any ‘no’ / ‘but’ and replay the last offer.</li><li>Clear obstacles first and agree a soft safety word before anyone closes their eyes.</li><li>If Follow the Voice frays, shrink the group size for one round, then rebuild to whole class.</li></ul><p><strong>Make it easier</strong></p><p>Reduce choices and model the first round together.</p><p><strong>Make it harder</strong></p><p>Layer dynamics (loud/soft, near/far) and keep a shared pulse.</p>',
    updated_at = NOW()
WHERE id = 'f3096c34-104f-4203-80f0-9676e1acc329';

