-- Drama tip refresh: News Reporters
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Open floor space. Work in small groups. No props needed. About 20 minutes.</p><p><strong>How to play</strong></p><ol><li>Pupils work in small groups to improvise a news report about an imaginary event (e.g</li><li>''a giant cat has appeared in the town square'')</li><li>They must create a reporter, a witness, and an expert</li></ol><p><strong>Teacher tips</strong></p><ul><li>Demand clear weight and size: if the audience can’t ‘see’ it, freeze and remime the first handle.</li><li>For News Reporters, allow one planning whisper only; then commit — stop the scene solely for safety or a clear reset.</li><li>Name one precise success after News Reporters (‘clear freeze’, ‘brave offer’) before you reset.</li></ul><p><strong>Make it easier</strong></p><p>Give a clearer prompt or allow a short planning whisper before performing.</p><p><strong>Make it harder</strong></p><p>Demand clearer weight, size and texture so the audience can ''see'' the object.</p><p><strong>Extension</strong></p><p>Replay the strongest 20 seconds and polish one offer.</p>',
    updated_at = NOW()
WHERE id = 'b9980310-768d-4d12-ac02-0cfb7ff70698';

