SET activity_text = '<p><strong>Setup</strong></p><p>Clear floor space for movement. No props needed. About 25 minutes.</p><p><strong>How to play</strong></p><ol><li>Gather attention and explain the game in one short sentence.</li><li>Pupils are given a character and a situation, and they must write and perform a short monologue from that character''s perspective.</li><li>Play a second round with a fresh prompt, then share one strong moment with the class.</li></ol><p><strong>Teacher tips</strong></p><ul><li>Before The Monologue, model the first ten seconds yourself so the rule is visible, not only explained.</li><li>After The Monologue, ask for one concrete example of good listening or a bold offer before you reset.</li><li>Name one precise success after The Monologue (‘clear freeze’, ‘brave offer’) before you reset.</li></ul><p><strong>Make it easier</strong></p><p>Give a clearer prompt or allow a short planning whisper before performing.</p><p><strong>Make it harder</strong></p><p>Raise the challenge with constraints (no words, fixed emotion, or a tighter time limit).</p>',
    updated_at = NOW()
