-- Drama tip refresh: Rhythm Circle
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Clear space so the class can sit or stand in a circle. No props needed. About 10 minutes.</p><p><strong>How to play</strong></p><ol><li>Pupils sit in a circle and pass a rhythm around by clapping, snapping, or stomping</li><li>The leader can change the rhythm or speed</li></ol><p><strong>Teacher tips</strong></p><ul><li>Keep the circle tight enough to hear; if the pass breaks, rewind two people and restart the chain.</li><li>After Rhythm Circle, ask for one concrete example of good listening or a bold offer before you reset.</li><li>If Rhythm Circle frays, shrink the group size for one round, then rebuild to whole class.</li></ul><p><strong>Make it easier</strong></p><p>Give a clearer prompt or allow a short planning whisper before performing.</p><p><strong>Make it harder</strong></p><p>Raise the challenge with constraints (no words, fixed emotion, or a tighter time limit).</p>',
    updated_at = NOW()
WHERE id = '6fad5b6a-b2c7-403a-94ed-915313b20a8c';

-- Drama tip refresh: The Memory Game
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Open floor space with clear pathways. Whole class. No props needed. About 15 minutes.</p><p><strong>How to play</strong></p><ol><li>A group of pupils mimes a series of actions (e.g. making a sandwich)</li><li>One person then leaves the room</li><li>The group changes one small detail of the mime, and the person who left has to guess what changed</li></ol><p><strong>Teacher tips</strong></p><ul><li>Demand clear weight and size: if the audience can’t ‘see’ it, freeze and remime the first handle.</li><li>After The Memory Game, ask for one concrete example of good listening or a bold offer before you reset.</li><li>If The Memory Game frays, shrink the group size for one round, then rebuild to whole class.</li></ul><p><strong>Make it easier</strong></p><p>Give a clearer prompt or allow a short planning whisper before performing.</p><p><strong>Make it harder</strong></p><p>Demand clearer weight, size and texture so the audience can ''see'' the object.</p>',
    updated_at = NOW()
WHERE id = 'baad0d75-b9d5-4312-8296-09756584039b';

