-- Drama tip refresh: The Soundscape Journey
UPDATE activities
SET activity_text = '<p><strong>Setup</strong></p><p>Clear floor space for movement. No props needed. About 20 minutes.</p><p><strong>How to play</strong></p><ol><li>The class creates a continuous soundscape of a journey (e.g. from the city to the forest)</li><li>They must listen and adapt their sounds as the scene changes</li></ol><p><strong>Teacher tips</strong></p><ul><li>Layer one sound at a time; conductor cuts with a flat hand so the texture doesn’t turn to noise.</li><li>For The Soundscape Journey, allow one planning whisper only; then commit — stop the scene solely for safety or a clear reset.</li><li>Name one precise success after The Soundscape Journey (‘clear freeze’, ‘brave offer’) before you reset.</li></ul><p><strong>Make it easier</strong></p><p>Give a clearer prompt or allow a short planning whisper before performing.</p><p><strong>Make it harder</strong></p><p>Layer dynamics (loud/soft, near/far) and keep a shared pulse.</p><p><strong>Extension</strong></p><p>Perform the soundscape under a short narrated story.</p>',
    updated_at = NOW()
WHERE id = 'b7b10544-8108-458f-aafb-7d0a7247f125';

